  ('LEADER_ADA_LOVELACE__AGENDA', 'LEADER_ADA_LOVELACE', 'TRAIT_LEADER_ADA_LOVELACE_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 0, 0, NULL, NULL),
  ('LEADER_ADA_LOVELACE__B01', 'LEADER_ADA_LOVELACE', 'TRAIT_LEADER_ADA_LOVELACE_ABILITY', 'bullet', 1, 1, NULL, '[icon:YIELD_CITIES] [B]Cities [/B]receive [B]+2[icon:YIELD_SCIENCE] Science [/B]per Age when you complete a [icon:RADIAL_CIVICS] [B]Civic Mastery[/B]. This resets at the start of each Age.', NULL, 3, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_ADA_LOVELACE__B02', 'LEADER_ADA_LOVELACE', 'TRAIT_LEADER_ADA_LOVELACE_ABILITY', 'bullet', 2, 1, NULL, 'Gain [B][icon:YIELD_CULTURE] Culture [/B]equal to 100% of your total [B][icon:YIELD_SCIENCE] Science [/B]per turn when you complete a [icon:RADIAL_TECH] [B]Technology Mastery[/B].[/LIST]', NULL, 3, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_ALEXANDER__AGENDA', 'LEADER_ALEXANDER', 'TRAIT_LEADER_ALEXANDER_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 0, 0, NULL, NULL),
  ('LEADER_ALEXANDER__B01', 'LEADER_ALEXANDER', 'TRAIT_LEADER_ALEXANDER_ABILITY', 'bullet', 1, 1, NULL, '[icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Cities[/TIP] other than your Capital with a [icon:WONDER] [TIP:LOC_PEDIA_CONCEPTS_WONDERS_TOOLTIP]Wonder[/TIP] get [B]+10% [icon:YIELD_PRODUCTION] Production[/B] and [icon:YIELD_CULTURE] [B]Culture[/B], doubled if they are on a different Continent than your [icon:NOTIFICATION_SELECT_CAPITAL] [TIP:LOC_PEDIA_CONCEPTS_CAPITAL_TOOLTIP]Capital[/TIP].', NULL, 3, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_ALEXANDER__B02', 'LEADER_ALEXANDER', 'TRAIT_LEADER_ALEXANDER_ABILITY', 'bullet', 2, 1, NULL, '[B]+2[/B] [icon:NAR_REW_COMBAT] [B][TIP:LOC_PEDIA_CONCEPTS_COMBAT_STRENGTH_TOOLTIP]Combat Strength[/TIP][/B] for [B]Land [TIP:LOC_PEDIA_CONCEPTS_MILITARY_UNIT_TOOLTIP]Military Units[/TIP][/B]. [B]+1 [icon:NAR_REW_COMBAT] Combat Strength[/B] for [B]Unique Military Units[/B] for every [icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]City[/TIP] with a [icon:WONDER] [TIP:LOC_PEDIA_CONCEPTS_WONDERS_TOOLTIP]Wonder[/TIP] other than your Capital (max 6).', NULL, 3, '|UNIT_CLASS_UNIQUE|', 1, 1, 1, 0, NULL, NULL),
  ('LEADER_ALEXANDER__B03', 'LEADER_ALEXANDER', 'TRAIT_LEADER_ALEXANDER_ABILITY', 'bullet', 3, 1, NULL, '[B]+2 [icon:MILITARY_VP] Dominion[/B] for every [icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]City[/TIP] with a [icon:WONDER] [TIP:LOC_PEDIA_CONCEPTS_WONDERS_TOOLTIP]Wonder[/TIP] other than your Capital.', NULL, 2, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_ALEXANDER__B04', 'LEADER_ALEXANDER', 'TRAIT_LEADER_ALEXANDER_ABILITY', 'bullet', 4, 1, NULL, '[icon:YIELD_TOWNS] [TIP:LOC_PEDIA_CONCEPTS_TOWN_TOOLTIP]Towns[/TIP] converted into [icon:YIELD_CITIES] [B]Cities[/B] are renamed after Alexander.[/LIST]', NULL, 1, NULL, 1, 1, 1, 0, NULL, 'Flavor only. Another leader holding it renames upgraded towns after Alexander.'),
  ('LEADER_AMINA__AGENDA', 'LEADER_AMINA', 'TRAIT_LEADER_AMINA_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 0, 0, NULL, NULL),
  ('LEADER_AMINA__B01', 'LEADER_AMINA', 'TRAIT_LEADER_AMINA_ABILITY', 'bullet', 1, 1, NULL, '+1 [icon:RADIAL_RESOURCES] [TIP:LOC_PEDIA_CONCEPTS_RESOURCE_CAPACITY_TOOLTIP]Resource Capacity[/TIP] in [icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Cities[/TIP].', NULL, 3, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_AMINA__B02', 'LEADER_AMINA', 'TRAIT_LEADER_AMINA_ABILITY', 'bullet', 2, 1, NULL, '+1 [icon:YIELD_GOLD] Gold per [TIP:LOC_PEDIA_CONCEPTS_AGE_TOOLTIP]Age[/TIP] for each [icon:RADIAL_RESOURCES] [TIP:LOC_PEDIA_CONCEPTS_RESOURCES_TOOLTIP]Resource[/TIP] assigned to [icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Cities[/TIP].', NULL, 2, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_AMINA__B03', 'LEADER_AMINA', 'TRAIT_LEADER_AMINA_ABILITY', 'bullet', 3, 1, NULL, '+5 [icon:NAR_REW_COMBAT] [TIP:LOC_PEDIA_CONCEPTS_COMBAT_STRENGTH_TOOLTIP]Combat Strength[/TIP] for [TIP:LOC_PEDIA_CONCEPTS_LAND_UNITS_TOOLTIP]Land Units[/TIP] in Plains and Desert.', '|BIOME_DESERT|BIOME_PLAINS|', 2, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_ASHOKA_ALT__AGENDA', 'LEADER_ASHOKA_ALT', 'TRAIT_LEADER_ASHOKA_ALT_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 0, 0, NULL, NULL),
  ('LEADER_ASHOKA_ALT__B01', 'LEADER_ASHOKA_ALT', 'TRAIT_LEADER_ASHOKA_ALT_ABILITY', 'bullet', 1, 1, NULL, '[B]+1[icon:YIELD_PRODUCTION] Production [/B]for every [B]5 [/B]excess [icon:YIELD_HAPPINESS] [B]Happiness [/B]in [icon:YIELD_CITIES] [B]Cities[/B].', NULL, 3, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_ASHOKA_ALT__B02', 'LEADER_ASHOKA_ALT', 'TRAIT_LEADER_ASHOKA_ALT_ABILITY', 'bullet', 2, 1, NULL, '[B]+10% [icon:YIELD_PRODUCTION] Production [/B]in Settlements not founded by you.', NULL, 2, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_ASHOKA_ALT__B03', 'LEADER_ASHOKA_ALT', 'TRAIT_LEADER_ASHOKA_ALT_ABILITY', 'bullet', 3, 1, NULL, 'Declaring a [icon:WAR] [B]Formal War [/B]grants a [icon:CELEBRATION] [B]Celebration[/B].', NULL, 3, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_ASHOKA_ALT__B04', 'LEADER_ASHOKA_ALT', 'TRAIT_LEADER_ASHOKA_ALT_ABILITY', 'bullet', 4, 1, NULL, '[B]+5 [icon:NAR_REW_COMBAT] Combat Strength[/B] against [icon:CITY_FORTIFIED] [B]Fortified Districts[/B] for all Units during a [icon:CELEBRATION] [B]Celebration[/B].[/LIST]', NULL, 2, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_ASHOKA__AGENDA', 'LEADER_ASHOKA', 'TRAIT_LEADER_ASHOKA_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 0, 0, NULL, NULL),
  ('LEADER_ASHOKA__B01', 'LEADER_ASHOKA', 'TRAIT_LEADER_ASHOKA_ABILITY', 'bullet', 1, 1, NULL, '+1 [icon:YIELD_FOOD] Food in [icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Cities[/TIP] for every 5 excess [icon:YIELD_HAPPINESS] Happiness.', NULL, 3, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_ASHOKA__B02', 'LEADER_ASHOKA', 'TRAIT_LEADER_ASHOKA_ABILITY', 'bullet', 2, 1, NULL, '+10% [icon:YIELD_FOOD] Food in Happy [TIP:LOC_PEDIA_CONCEPTS_SETTLEMENT_TOOLTIP]Settlements[/TIP] during a [icon:CELEBRATION] [TIP:LOC_PEDIA_CONCEPTS_CELEBRATIONS_TOOLTIP]Celebration[/TIP], or 15% in Joyous Settlements, or 20% in Ecstatic Settlements.', NULL, 2, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_ASHOKA__B03', 'LEADER_ASHOKA', 'TRAIT_LEADER_ASHOKA_ABILITY', 'bullet', 3, 1, NULL, '[icon:CITY_BUILDING_LIST] Unique, [icon:YIELD_HAPPINESS] Happiness, and [icon:YIELD_FOOD] Food [TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Buildings[/TIP] gain a +1 [icon:YIELD_HAPPINESS] Happiness adjacency for all [icon:CITY_RURAL] Improvements.', NULL, 3, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_AUGUSTUS__AGENDA', 'LEADER_AUGUSTUS', 'TRAIT_LEADER_AUGUSTUS_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 0, 0, NULL, NULL),
  ('LEADER_AUGUSTUS__B01', 'LEADER_AUGUSTUS', 'TRAIT_LEADER_AUGUSTUS_ABILITY', 'bullet', 1, 1, NULL, '+2 [icon:YIELD_PRODUCTION] Production in the [icon:NOTIFICATION_SELECT_CAPITAL] Capital for every [icon:YIELD_TOWNS] [TIP:LOC_PEDIA_CONCEPTS_TOWN_TOOLTIP]Town[/TIP].', NULL, 4, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_AUGUSTUS__B02', 'LEADER_AUGUSTUS', 'TRAIT_LEADER_AUGUSTUS_ABILITY', 'bullet', 2, 1, NULL, 'Can purchase [icon:YIELD_CULTURE] Culture [TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Buildings[/TIP] in [icon:YIELD_TOWNS] [TIP:LOC_PEDIA_CONCEPTS_TOWN_TOOLTIP]Towns[/TIP] with any Focus.', NULL, 2, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_AUGUSTUS__B03', 'LEADER_AUGUSTUS', 'TRAIT_LEADER_AUGUSTUS_ABILITY', 'bullet', 3, 1, NULL, '+15% [icon:YIELD_GOLD] Gold towards purchasing [icon:CITY_BUILDING_LIST] [TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Buildings[/TIP] in [icon:YIELD_TOWNS] [TIP:LOC_PEDIA_CONCEPTS_TOWN_TOOLTIP]Towns[/TIP]. Doubled if that [TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Building[/TIP] is present in your [icon:NOTIFICATION_SELECT_CAPITAL] Capital.', NULL, 2, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_Akyuu__AGENDA', 'LEADER_Akyuu', 'TRAIT_LEADER_Akyuu_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 0, 1, 'MAO-Leader-Akyuu', NULL),
  ('LEADER_Akyuu__B01', 'LEADER_Akyuu', 'TRAIT_LEADER_Akyuu_ABILITY', 'bullet', 1, 1, NULL, '[B]Gensokyo Chronicle:[/B] Start with [B]+1[/B] [icon:NAR_REW_TRADITION_SLOT]Tradition slot and unlock Greek tradition "Xenia I". Each unique civilization [icon:TRADITION]Tradition grants [B]+3/6/12[/B] [icon:YIELD_CULTURE]Culture.', NULL, 3, NULL, 1, 1, 1, 1, 'MAO-Leader-Akyuu', NULL),
  ('LEADER_Akyuu__B02', 'LEADER_Akyuu', 'TRAIT_LEADER_Akyuu_ABILITY', 'bullet', 2, 2, NULL, '[B]Perfect Memory:[/B] Completing [icon:NAR_REW_DEFAULT]Narrative Events grants [B]+15/30/60[/B] [icon:YIELD_SCIENCE]Science. Knowledge preserved forever![N][B]Gumon Shiki:[/B] Unique [icon:NAR_REW_DEFAULT]Narrative storyline. Across three Ages, chronicle and collect 30 [icon:TRADITION]Traditions from civilizations around the world![/LIST]', NULL, 2, NULL, 1, 1, 1, 1, 'MAO-Leader-Akyuu', 'Bullet 3 merged in: one effect serves both.'),
  ('LEADER_Aya__AGENDA', 'LEADER_Aya', 'TRAIT_LEADER_Aya_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 0, 1, 'MAO-Leader-Aya', NULL),
  ('LEADER_Aya__B01', 'LEADER_Aya', 'TRAIT_LEADER_Aya_ABILITY', 'bullet', 1, 1, NULL, '[B]Exclusive Scoop:[/B] Every [B]10[/B] tiles explored grants [B]+2[/B] [icon:YIELD_DIPLOMACY]Influence and [B]+2[/B] [icon:YIELD_GOLD]Gold. Discovering a [icon:NOTIFICATION_DISCOVER_NATURAL_WONDER]Natural Wonder grants [B]+30/60/120[/B] [icon:YIELD_DIPLOMACY]Influence (extra +30/60/120 if distant). Completing [icon:NAR_REW_DEFAULT]Narrative Events grants [B]+10/20/40[/B] [icon:YIELD_GOLD]Gold. News is everywhere!', '|NATURAL_WONDER|', 3, NULL, 1, 1, 1, 1, 'MAO-Leader-Aya', NULL),
  ('LEADER_Aya__B02', 'LEADER_Aya', 'TRAIT_LEADER_Aya_ABILITY', 'bullet', 2, 1, NULL, '[B]Fantasy Wind:[/B] Except Navigable Rivers, all [icon:CITY_UNIMPROVED]Terrain and Rivers do not exhaust unit [icon:Action_Move]Movement. Units adjacent to Mountains gain [B]+2[/B] [icon:Action_Showall]Sight.', '|TERRAIN_HILL|TERRAIN_MOUNTAIN|', 3, NULL, 1, 1, 1, 1, 'MAO-Leader-Aya', NULL),
  ('LEADER_Aya__B03', 'LEADER_Aya', 'TRAIT_LEADER_Aya_ABILITY', 'bullet', 3, 1, NULL, '[B]Fastest Reporter:[/B] [B]+50%[/B] Diplomatic Endeavor Efficiency. A news network that spans the world![/LIST]', NULL, 2, NULL, 1, 1, 1, 1, 'MAO-Leader-Aya', NULL),
  ('LEADER_BENJAMIN_FRANKLIN__AGENDA', 'LEADER_BENJAMIN_FRANKLIN', 'TRAIT_LEADER_BENJAMIN_FRANKLIN_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 1, 0, NULL, 'Includes agenda modifiers beyond DIPLOMACY_AGENDA_TIMED_UPDATE; check they belong with the personality.'),
  ('LEADER_BENJAMIN_FRANKLIN__B01', 'LEADER_BENJAMIN_FRANKLIN', 'TRAIT_LEADER_BENJAMIN_FRANKLIN_ABILITY', 'bullet', 1, 1, NULL, '+1 [icon:YIELD_SCIENCE] Science per [TIP:LOC_PEDIA_CONCEPTS_AGE_TOOLTIP]Age[/TIP] on [icon:YIELD_PRODUCTION] Production and [icon:YIELD_SCIENCE] Science [icon:CITY_BUILDING_LIST] [TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Buildings[/TIP] in [icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Cities[/TIP].', NULL, 3, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_BENJAMIN_FRANKLIN__B02', 'LEADER_BENJAMIN_FRANKLIN', 'TRAIT_LEADER_BENJAMIN_FRANKLIN_ABILITY', 'bullet', 2, 1, NULL, '+5% [icon:YIELD_PRODUCTION] Production towards constructing [icon:CITY_BUILDING_LIST] [TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Buildings[/TIP] for active [icon:ENDEAVOR] Endeavors you have started or supported.', NULL, 2, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_BENJAMIN_FRANKLIN__B03', 'LEADER_BENJAMIN_FRANKLIN', 'TRAIT_LEADER_BENJAMIN_FRANKLIN_ABILITY', 'bullet', 3, 1, NULL, '+2 [icon:YIELD_SCIENCE] Science per [TIP:LOC_PEDIA_CONCEPTS_AGE_TOOLTIP]Age[/TIP] from active [icon:ENDEAVOR] [TIP:LOC_PEDIA_CONCEPTS_ENDEAVOR_TOOLTIP]Endeavors[/TIP] you started or supported.', NULL, 2, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_BENJAMIN_FRANKLIN__B04', 'LEADER_BENJAMIN_FRANKLIN', 'TRAIT_LEADER_BENJAMIN_FRANKLIN_ABILITY', 'bullet', 4, 1, NULL, 'Can have two [icon:ENDEAVOR] [TIP:LOC_PEDIA_CONCEPTS_ENDEAVOR_TOOLTIP]Endeavors[/TIP] of the same type active at a time.', NULL, 1, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_BOLIVAR__AGENDA', 'LEADER_BOLIVAR', 'TRAIT_LEADER_BOLIVAR_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 0, 0, NULL, NULL),
  ('LEADER_BOLIVAR__B01', 'LEADER_BOLIVAR', 'TRAIT_LEADER_BOLIVAR_ABILITY', 'bullet', 1, 1, NULL, 'Gain [B]2 [icon:WAR_SUPPORT] War Support [/B]on [icon:WAR] [B]Wars[/B] you declare.', NULL, 2, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_BOLIVAR__B02', 'LEADER_BOLIVAR', 'TRAIT_LEADER_BOLIVAR_ABILITY', 'bullet', 2, 1, NULL, 'When you conquer a Settlement for the first time the Settlement can [B]purchase 1 [icon:CITY_BUILDING_LIST] Building or [icon:CITY_RURAL] Improvement for free[/B].', NULL, 3, NULL, 1, 1, 1, 0, NULL, NULL);
