  ('LEADER_Bocchi__B02', 'LEADER_Bocchi', 'TRAIT_LEADER_BOCCHI_ABILITY', 'bullet', 2, 1, NULL, '[B]Shining Alone:[/B] With no [icon:PLAYER_RELATIONSHIP_FRIENDLY]Friendly or [icon:PLAYER_RELATIONSHIP_HELPFUL]Helpful relationships, [icon:YIELD_HAPPINESS][B]+30% Happiness[/B]. Each leader with either relationship grants [B]+4/8/16[/B][icon:YIELD_GOLD]Gold, [icon:YIELD_SCIENCE]Science, [icon:YIELD_CULTURE]Culture (scales with Age).[/LI][N][BLIST]', NULL, 3, NULL, 1, 1, 1, 1, 'MAO-Leader-Bocchi', NULL),
  ('LEADER_Bocchi__B03', 'LEADER_Bocchi', 'TRAIT_LEADER_BOCCHI_ABILITY', 'bullet', 3, 1, NULL, '[B]Closet Life:[/B] [icon:TRADE_ROUTE]Trade Route capacity [B]-1[/B], Trade Range [B]-50[/B]; each [icon:TRADE]Imported Resource grants [icon:YIELD_CULTURE][B]+2/4/8 Culture[/B] (scales with Age).[/LI]', NULL, 2, NULL, 1, 1, 1, 1, 'MAO-Leader-Bocchi', NULL),
