  ('LEADER_CATHERINE__B03', 'LEADER_CATHERINE', 'TRAIT_LEADER_CATHERINE_ABILITY', 'bullet', 3, 1, NULL, '[icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Cities[/TIP] settled in Tundra gain [icon:YIELD_SCIENCE] Science equal to 25% of their [icon:YIELD_CULTURE] Culture per turn.', '|BIOME_TUNDRA|', 2, NULL, 1, 1, 1, 0, NULL, NULL),
