  ('LEADER_CONFUCIUS__B02', 'LEADER_CONFUCIUS', 'TRAIT_LEADER_CONFUCIUS_ABILITY', 'bullet', 2, 1, NULL, '+2 [icon:YIELD_SCIENCE] Science from [icon:SPECIALIST] [TIP:LOC_PEDIA_CONCEPTS_SPECIALIST_TOOLTIP]Specialists[/TIP].', NULL, 4, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_Cirno__AGENDA', 'LEADER_Cirno', 'TRAIT_LEADER_Cirno_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 0, 1, 'MAO-Leader-Cirno', NULL),
  ('LEADER_Cirno__B01', 'LEADER_Cirno', 'TRAIT_LEADER_Cirno_ABILITY', 'bullet', 1, 1, NULL, '[B]Perfect Freeze:[/B] Your units are immune to [icon:RANDOM_EVENT]blizzard damage; Units in tundra gain [B]+1[/B] Agility [B]+2[/B] Bravery [B]+⑨[/B] Strength = ？[/LI][N][BLIST]', '|BIOME_TUNDRA|', 2, NULL, 1, 1, 1, 1, 'MAO-Leader-Cirno', NULL),
  ('LEADER_Cirno__B02', 'LEADER_Cirno', 'TRAIT_LEADER_Cirno_ABILITY', 'bullet', 2, 1, NULL, '[B]Perfect Math:[/B] [icon:YIELD_CITIES]Cities have [B]-90%[/B] [icon:YIELD_SCIENCE]Science and [B]500%[/B] [icon:YIELD_HAPPINESS]Happiness converts to [icon:YIELD_SCIENCE]Science.[N][icon:YIELD_TOWNS]Towns skip the penalty and conversion; [icon:YIELD_SCIENCE]Science buildings gain [B]+1[/B] [icon:YIELD_HAPPINESS]Happiness adjacency from [icon:RESOURCE]Resources and [icon:WONDER]Wonders.[N]All [icon:YIELD_SCIENCE]Science buildings [B]+900%[/B] build speed and [B]+90%[/B] [icon:YIELD_GOLD]Gold purchase efficiency.[N]All [icon:SPECIALIST]Specialists gain [B]+200%[/B] [icon:YIELD_HAPPINESS]Happiness maintenance efficiency.[/LI]', NULL, 4, NULL, 1, 1, 1, 1, 'MAO-Leader-Cirno', NULL),
  ('LEADER_EDWARD_TEACH__AGENDA', 'LEADER_EDWARD_TEACH', 'TRAIT_LEADER_EDWARD_TEACH_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, '|UNIT_CLASS_NAVAL|', 1, 1, 0, 0, NULL, NULL),
  ('LEADER_EDWARD_TEACH__B01', 'LEADER_EDWARD_TEACH', 'TRAIT_LEADER_EDWARD_TEACH_ABILITY', 'bullet', 1, 1, NULL, 'All Naval Units gain the [icon:UNIT_CAUTION] [B]Pirate Ability[/B], allowing them to cross borders of other Civilizations, [icon:Action_Pillage] [B]Plunder Trade Routes[/B] from non-Allied Civilizations, and attack Units of non-Allied Civilizations [B]without declaring [icon:WAR] War[/B].', '|COAST|', 3, '|UNIT_CLASS_COMBAT|UNIT_CLASS_FLEET_COMMANDER|', 1, 1, 1, 0, NULL, NULL),
  ('LEADER_EDWARD_TEACH__B02', 'LEADER_EDWARD_TEACH', 'TRAIT_LEADER_EDWARD_TEACH_ABILITY', 'bullet', 2, 1, NULL, 'Defeating any Naval Unit with your own Naval Units provides [B][icon:YIELD_GOLD] Gold[/B] equal to 50% of its [icon:NAR_REW_COMBAT] [B]Combat Strength[/B] and captures that Unit under your control.', '|COAST|', 3, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_EDWARD_TEACH__B03', 'LEADER_EDWARD_TEACH', 'TRAIT_LEADER_EDWARD_TEACH_ABILITY', 'bullet', 3, 1, NULL, '[B]+1 [icon:YIELD_GOLD] Gold [/B]Maintenance for [B]Naval Units[/B].[/LIST]', '|COAST|', 1, '|UNIT_CLASS_NAVAL|', 1, 1, 1, 0, NULL, 'A drawback (+1 Gold maintenance). The 1 to 5 scale has no negative, so it''s a 1.'),
  ('LEADER_EIRIN__AGENDA', 'LEADER_EIRIN', 'TRAIT_LEADER_EIRIN_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 0, 1, 'MAO-Leader-EIRIN', NULL),
  ('LEADER_EIRIN__B01', 'LEADER_EIRIN', 'TRAIT_LEADER_EIRIN_ABILITY', 'bullet', 1, 1, NULL, '[B]Brain of the Moon:[/B] All [icon:YIELD_WAREHOUSE]Warehouse buildings gain [B]+1[/B] base yields. [B]+20%[/B] [icon:YIELD_SCIENCE]Science towards researching [icon:RADIAL_TECH]Technologies.', NULL, 4, NULL, 1, 1, 1, 1, 'MAO-Leader-EIRIN', NULL),
  ('LEADER_EIRIN__B02', 'LEADER_EIRIN', 'TRAIT_LEADER_EIRIN_ABILITY', 'bullet', 2, 1, NULL, '[B]Hourai Elixir:[/B] All [icon:CITY_BUILDING_LIST]Building [icon:YIELD_GOLD]Maintenance efficiency [B]+100%[/B] (maintenance cost halved). All settlements [B]cannot be damaged by [icon:YIELD_PLAGUE]Plague[/B].', NULL, 3, NULL, 1, 1, 1, 1, 'MAO-Leader-EIRIN', NULL),
  ('LEADER_EIRIN__B03', 'LEADER_EIRIN', 'TRAIT_LEADER_EIRIN_ABILITY', 'bullet', 3, 1, NULL, '[B]Moon Forsaker:[/B] [icon:YIELD_DISTANT_LANDS]Distant Lands settlements: [icon:GROWTH_RATE]Growth Rate [B]+30%[/B], [icon:YIELD_HAPPINESS]Happiness [B]+5[/B], first [icon:CITY_BUILDING_LIST]Building is [B]free[/B].[/LIST]', NULL, 3, NULL, 1, 1, 1, 1, 'MAO-Leader-EIRIN', NULL),
  ('LEADER_ELIZABETH__AGENDA', 'LEADER_ELIZABETH', 'TRAIT_LEADER_ELIZABETH_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 0, 0, NULL, NULL),
  ('LEADER_ELIZABETH__B01', 'LEADER_ELIZABETH', 'TRAIT_LEADER_ELIZABETH_ABILITY', 'bullet', 1, 1, NULL, 'Unlimited [icon:TRADE_ROUTE] [TIP:LOC_PEDIA_CONCEPTS_TRADE_ROUTE_TOOLTIP]Trade Route[/TIP] Range.', NULL, 3, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_ELIZABETH__B02', 'LEADER_ELIZABETH', 'TRAIT_LEADER_ELIZABETH_ABILITY', 'bullet', 2, 1, NULL, 'When you found a [TIP:LOC_PEDIA_CONCEPTS_SETTLEMENT_TOOLTIP]Settlement[/TIP] on a different [TIP:LOC_PEDIA_CONCEPTS_CONTINENT_TOOLTIP]Continent[/TIP] than your [icon:NOTIFICATION_SELECT_CAPITAL] [TIP:LOC_PEDIA_CONCEPTS_CAPITAL_TOOLTIP]Capital[/TIP], receive a [icon:NAR_REW_GREATWORK] [TIP:LOC_PEDIA_CONCEPTS_GREAT_WORKS_TOOLTIP]Great Work[/TIP].', '|COAST|', 2, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_ELIZABETH__B03', 'LEADER_ELIZABETH', 'TRAIT_LEADER_ELIZABETH_ABILITY', 'bullet', 3, 1, NULL, '+2 [icon:Action_Move] Movement to [TIP:LOC_PEDIA_CONCEPTS_NAVAL_UNITS_TOOLTIP]Naval Units[/TIP], [TIP:LOC_PEDIA_CONCEPTS_EMBARK_TOOLTIP]Embarked[/TIP] [icon:UNIT_SETTLER] Settlers, and Embarked [icon:UNIT_MERCHANT] Merchants. [icon:UNIT_MERCHANT] Merchants and [icon:UNIT_SETTLER] Settlers are 15% cheaper to purchase.', '|COAST|', 3, '|UNIT_CLASS_CREATE_TOWN|UNIT_CLASS_MAKE_TRADE_ROUTE|UNIT_CLASS_NAVAL|', 1, 1, 1, 0, NULL, NULL),
  ('LEADER_ELIZABETH__B04', 'LEADER_ELIZABETH', 'TRAIT_LEADER_ELIZABETH_ABILITY', 'bullet', 4, 1, NULL, '-2 [icon:NAR_REW_COMBAT] [TIP:LOC_PEDIA_CONCEPTS_COMBAT_STRENGTH_TOOLTIP]Combat Strength[/TIP] to Land Combat Units per Age.[/LIST]', NULL, 1, NULL, 1, 1, 1, 0, NULL, 'A drawback; scored 1.'),
  ('LEADER_Ema__AGENDA', 'LEADER_Ema', 'TRAIT_LEADER_Ema_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 0, 1, 'MAO-Leader-MahoShojoWitchTrial', NULL),
  ('LEADER_Ema__B01', 'LEADER_Ema', 'TRAIT_LEADER_Ema_ABILITY', 'bullet', 1, 1, NULL, '[B]Witch Hunt:[/B][icon:NAR_REW_COMBAT][B]+8[/B] Combat Strength against enemy [icon:UNIT_ARMY_COMMANDER]Commanders. Gain [B]150/300/600[/B][icon:YIELD_CULTURE]Culture when defeating enemy [icon:UNIT_ARMY_COMMANDER]Commanders.', NULL, 3, '|UNIT_CLASS_COMMAND|', 1, 1, 1, 1, 'MAO-Leader-MahoShojoWitchTrial', NULL),
  ('LEADER_Ema__B02', 'LEADER_Ema', 'TRAIT_LEADER_Ema_ABILITY', 'bullet', 2, 1, NULL, '[B]Heart of Bonds:[/B][B]+5/10/20[/B][icon:YIELD_DIPLOMACY]Influence per [icon:PLAYER_RELATIONSHIP_FRIENDLY]Friendly, [icon:PLAYER_RELATIONSHIP_HELPFUL]Helpful, or [icon:PLAYER_RELATIONSHIP_ALLIANCE]Alliance relationship. All units gain [icon:NAR_REW_COMBAT][B]+3[/B] Combat Strength per [icon:PLAYER_RELATIONSHIP_ALLIANCE]Alliance (max 2 = +6).', NULL, 3, NULL, 1, 1, 1, 1, 'MAO-Leader-MahoShojoWitchTrial', NULL),
  ('LEADER_Ema__B03', 'LEADER_Ema', 'TRAIT_LEADER_Ema_ABILITY', 'bullet', 3, 1, NULL, '[B]Warmth of Protection:[/B] All [TIP:LOC_PEDIA_CONCEPTS_DEFENSIVE_FORTIFICATION_TOOLTIP]Defensive Fortifications[/TIP] (including [B]Improvements[/B]) gain [B]+2[/B][icon:YIELD_HAPPINESS]Happiness.[/LIST][N]Special Diplomatic Actions: [icon:WITCH_TRIAL_PACT][B]Witch Trial Pact[/B] and [icon:WITCH_VERDICT][B]Witch Verdict[/B].', NULL, 2, NULL, 1, 1, 1, 1, 'MAO-Leader-MahoShojoWitchTrial', 'The two special diplomatic actions are named in text that sits inside this bullet (after its [/LIST]), so their unlocks travel here as hidden rows.'),
  ('LEADER_FLAN__AGENDA', 'LEADER_FLAN', 'TRAIT_LEADER_FLAN_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 0, 1, 'MAO-Leader-Flan', NULL),
  ('LEADER_FLAN__B01', 'LEADER_FLAN', 'TRAIT_LEADER_FLAN_ABILITY', 'bullet', 1, 1, NULL, '[B]Quadruple Existence:[/B] When gaining your first [icon:UNIT_ARMY_COMMANDER]Military Commander, receive another [icon:UNIT_ARMY_COMMANDER]Military Commander in your [icon:CITY_CAPITAL]Capital with [B]1[/B] Melee, [B]1[/B] Ranged, and [B]1[/B] Siege unit. These units will appear even if not yet unlocked.[N][N][BLIST]', NULL, 3, '|UNIT_ARMY_COMMANDER|UNIT_CLASS_MELEE|UNIT_CLASS_RANGED|UNIT_CLASS_SIEGE|', 1, 1, 1, 1, 'MAO-Leader-Flan', NULL),
  ('LEADER_FLAN__B02', 'LEADER_FLAN', 'TRAIT_LEADER_FLAN_ABILITY', 'bullet', 2, 1, NULL, '[B]Eye of Destruction:[/B] [B]+20[/B] [icon:NAR_REW_COMBAT]Combat Strength vs [icon:DAMAGED]enemies below [B]30%[/B] HP; [icon:DOMAIN_LAND]Land military units [B]+5[/B] [icon:NAR_REW_COMBAT]Combat Strength vs City Districts.[N][N][BLIST]', NULL, 3, NULL, 1, 1, 1, 1, 'MAO-Leader-Flan', NULL),
  ('LEADER_FLAN__B03', 'LEADER_FLAN', 'TRAIT_LEADER_FLAN_ABILITY', 'bullet', 3, 1, NULL, '[B]Caged Bird:[/B] Heal [B]100[/B] [icon:Action_Heal]HP after capturing cities; [icon:CITY_PILLAGED]Raze progress [B]+1[/B] per turn (faster razing), but [icon:Action_Pillage]Pillage yields [B]-50%[/B](Destoryed by Flandre).[N][N][BLIST]', NULL, 2, '|UNIT_CLASS_INFANTRY|', 1, 1, 1, 1, 'MAO-Leader-Flan', NULL);
INSERT OR IGNORE INTO LShufMapping (PieceId, LeaderType, AbilityTrait, Kind, BulletIndex, BulletCount, BulletList, BulletText, BiasTags, Value, SpecificTo, Movable, Reviewed, Guess, IsModded, ModId, Note) VALUES
  ('LEADER_FLAN__B04', 'LEADER_FLAN', 'TRAIT_LEADER_FLAN_ABILITY', 'bullet', 4, 1, NULL, '[B]495 Years of Solitude:[/B] [icon:SETTLEMENT_LIMIT]Settlement cap permanently [B]-2[/B], but [B]+1[/B] [icon:SETTLEMENT_LIMIT]Settlement cap for each conquered city.', NULL, 1, NULL, 1, 1, 1, 1, 'MAO-Leader-Flan', 'Mostly a drawback; scored 1.'),
  ('LEADER_FRIEDRICH_ALT__AGENDA', 'LEADER_FRIEDRICH_ALT', 'TRAIT_LEADER_FRIEDRICH_ALT_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 0, 0, NULL, NULL),
  ('LEADER_FRIEDRICH_ALT__B01', 'LEADER_FRIEDRICH_ALT', 'TRAIT_LEADER_FRIEDRICH_ALT_ABILITY', 'bullet', 1, 1, NULL, 'Gain a [icon:NAR_REW_GREATWORK] [TIP:LOC_PEDIA_CONCEPTS_GREAT_WORKS_TOOLTIP]Great Work[/TIP] when you capture a [TIP:LOC_PEDIA_CONCEPTS_SETTLEMENT_TOOLTIP]Settlement[/TIP] for the first time.', NULL, 2, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_FRIEDRICH_ALT__B02', 'LEADER_FRIEDRICH_ALT', 'TRAIT_LEADER_FRIEDRICH_ALT_ABILITY', 'bullet', 2, 1, NULL, '+1 [icon:YIELD_CULTURE] Culture per [TIP:LOC_PEDIA_CONCEPTS_AGE_TOOLTIP]Age[/TIP] on displayed [icon:NAR_REW_GREATWORK] Great Works.', NULL, 2, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_FRIEDRICH_ALT__B03', 'LEADER_FRIEDRICH_ALT', 'TRAIT_LEADER_FRIEDRICH_ALT_ABILITY', 'bullet', 3, 1, NULL, 'Gain an [TIP:LOC_PEDIA_CONCEPTS_INFANTRY_UNITS_TOOLTIP]Infantry Unit[/TIP] in your [icon:NOTIFICATION_SELECT_CAPITAL] [TIP:LOC_PEDIA_CONCEPTS_CAPITAL_TOOLTIP]Capital[/TIP] when you complete a [TIP:LOC_PEDIA_CONCEPTS_MASTERY_TOOLTIP]Civic Mastery[/TIP], and in [TIP:LOC_PEDIA_CONCEPTS_SETTLEMENT_TOOLTIP]Settlements[/TIP] where you construct a [icon:YIELD_CULTURE] [TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Culture Building[/TIP].[/LIST]', NULL, 3, '|UNIT_CLASS_INFANTRY|', 1, 1, 1, 0, NULL, NULL),
  ('LEADER_FRIEDRICH__AGENDA', 'LEADER_FRIEDRICH', 'TRAIT_LEADER_FRIEDRICH_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 0, 0, NULL, NULL),
  ('LEADER_FRIEDRICH__B01', 'LEADER_FRIEDRICH', 'TRAIT_LEADER_FRIEDRICH_ABILITY', 'bullet', 1, 1, NULL, '[icon:UNIT_ARMY_COMMANDER] [TIP:LOC_PEDIA_CONCEPTS_COMMANDER_TOOLTIP]Army Commanders[/TIP] start with the Merit [TIP:LOC_PEDIA_CONCEPTS_COMMENDATION_TOOLTIP]Commendation[/TIP], granting them +1 [icon:COMMANDER_RADIUS] [TIP:LOC_PEDIA_CONCEPTS_COMMAND_RADIUS_TOOLTIP]Command Radius[/TIP].', NULL, 2, '|UNIT_CLASS_ARMY_COMMANDER|', 1, 1, 1, 0, NULL, NULL),
  ('LEADER_FRIEDRICH__B02', 'LEADER_FRIEDRICH', 'TRAIT_LEADER_FRIEDRICH_ABILITY', 'bullet', 2, 1, NULL, 'Gain an [TIP:LOC_PEDIA_CONCEPTS_INFANTRY_UNITS_TOOLTIP]Infantry Unit[/TIP] in your [icon:NOTIFICATION_SELECT_CAPITAL] [TIP:LOC_PEDIA_CONCEPTS_CAPITAL_TOOLTIP]Capital[/TIP] when you complete a [icon:RADIAL_TECH] [TIP:LOC_PEDIA_CONCEPTS_TECH_TOOLTIP]Technology Mastery[/TIP], and in [TIP:LOC_PEDIA_CONCEPTS_SETTLEMENT_TOOLTIP]Settlements[/TIP] where you construct a [icon:YIELD_SCIENCE] [TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Science Building[/TIP].', NULL, 3, '|UNIT_CLASS_INFANTRY|', 1, 1, 1, 0, NULL, NULL),
  ('LEADER_FRIEDRICH__B03', 'LEADER_FRIEDRICH', 'TRAIT_LEADER_FRIEDRICH_ABILITY', 'bullet', 3, 1, NULL, '+2 [icon:YIELD_SCIENCE] Science per [TIP:LOC_PEDIA_CONCEPTS_AGE_TOOLTIP]Age[/TIP] for each [TIP:LOC_PEDIA_CONCEPTS_COMMENDATION_TOOLTIP]Commendation[/TIP] earned by your [TIP:LOC_PEDIA_CONCEPTS_COMMANDER_TOOLTIP]Commanders[/TIP].', NULL, 2, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_GENGHIS_KHAN__AGENDA', 'LEADER_GENGHIS_KHAN', 'TRAIT_LEADER_GENGHIS_KHAN_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, '|UNIT_CLASS_CAVALRY|', 1, 1, 0, 0, NULL, NULL),
  ('LEADER_GENGHIS_KHAN__B01', 'LEADER_GENGHIS_KHAN', 'TRAIT_LEADER_GENGHIS_KHAN_ABILITY', 'bullet', 1, 1, NULL, '[B]+3 [icon:NAR_REW_COMBAT] Combat Strength [/B]for [B]Cavalry Units[/B], or [B]+5[/B] when in an [B]Army [icon:COMMANDER_RADIUS] Command Radius[/B].', NULL, 3, '|UNIT_CLASS_CAVALRY|', 1, 1, 1, 0, NULL, 'The +5 inside a command radius comes from ABILITY_GENGHIS_KHAN_COMMAND_RADIUS_COMBAT, which bullet 2''s modifier grants.'),
  ('LEADER_GENGHIS_KHAN__B02', 'LEADER_GENGHIS_KHAN', 'TRAIT_LEADER_GENGHIS_KHAN_ABILITY', 'bullet', 2, 2, NULL, '[icon:UNIT_ARMY_COMMANDER] [B]Army Commanders [/B]have [B]+1 [icon:Action_Move] Movement [/B]even when no Units are packed into them.[N]Once per Age, [icon:UNIT_ARMY_COMMANDER] [B]Army Commanders [/B]can use the [B]Convert Independents Action[/B] to convert adjacent [icon:INDEPENDENT_POWER] [B]Independent Military Units [/B]to your control.[/LIST]', NULL, 3, '|UNIT_CLASS_CAVALRY|', 1, 1, 1, 0, NULL, 'One modifier does bullets 2 and 3 (and the +5 of bullet 1), so whoever holds this piece gets all three. Bullet 3 merged in: one effect serves both.'),
  ('LEADER_GILGAMESH__AGENDA', 'LEADER_GILGAMESH', 'TRAIT_LEADER_GILGAMESH_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 0, 0, NULL, NULL),
  ('LEADER_GILGAMESH__B01', 'LEADER_GILGAMESH', 'TRAIT_LEADER_GILGAMESH_ABILITY', 'bullet', 1, 1, NULL, '+2 [B][icon:WAR_SUPPORT] War Support[/B] when in only one [icon:PLAYER_RELATIONSHIP_ALLIANCE] Alliance.', NULL, 2, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_GILGAMESH__B02', 'LEADER_GILGAMESH', 'TRAIT_LEADER_GILGAMESH_ABILITY', 'bullet', 2, 1, NULL, 'When one of your Military Units defeats an enemy Unit, gain [B][icon:YIELD_DIPLOMACY] Influence[/B] equal to 50% of the defeated Unit''s [icon:NAR_REW_COMBAT] Combat Strength.', NULL, 2, '|UNIT_CLASS_COMBAT|', 1, 1, 1, 0, NULL, NULL),
  ('LEADER_GILGAMESH__B03', 'LEADER_GILGAMESH', 'TRAIT_LEADER_GILGAMESH_ABILITY', 'bullet', 3, 1, NULL, 'All basic Endeavors are automatically unlocked. Endeavors with Allies don’t count against the limit of having one Endeavor of a given type active at a time. Allies can support your Endeavors for free. [/LIST]', NULL, 3, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_HARRIET_TUBMAN__AGENDA', 'LEADER_HARRIET_TUBMAN', 'TRAIT_LEADER_HARRIET_TUBMAN_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 1, 0, NULL, 'Includes agenda modifiers beyond DIPLOMACY_AGENDA_TIMED_UPDATE; check they belong with the personality.'),
  ('LEADER_HARRIET_TUBMAN__B01', 'LEADER_HARRIET_TUBMAN', 'TRAIT_LEADER_HARRIET_TUBMAN_ABILITY', 'bullet', 1, 1, NULL, '+100% [icon:YIELD_DIPLOMACY] Influence towards initiating [icon:ESPIONAGE] [TIP:LOC_PEDIA_CONCEPTS_ESPIONAGE_TOOLTIP]Espionage[/TIP] Actions. Gain a Migrant in the Capital whenever you complete an [TIP:LOC_PEDIA_CONCEPTS_ESPIONAGE_TOOLTIP]Espionage[/TIP] Action without being detected.', NULL, 3, '|UNIT_MIGRANT|', 1, 1, 1, 0, NULL, NULL),
  ('LEADER_HARRIET_TUBMAN__B02', 'LEADER_HARRIET_TUBMAN', 'TRAIT_LEADER_HARRIET_TUBMAN_ABILITY', 'bullet', 2, 1, NULL, 'Gain 5 [icon:WAR_SUPPORT] [TIP:LOC_PEDIA_CONCEPTS_WAR_SUPPORT_TOOLTIP]War Support[/TIP] on all [icon:WAR] Wars declared against you.', NULL, 2, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_HARRIET_TUBMAN__B03', 'LEADER_HARRIET_TUBMAN', 'TRAIT_LEADER_HARRIET_TUBMAN_ABILITY', 'bullet', 3, 1, NULL, '[icon:CITY_UNIMPROVED] [TIP:LOC_PEDIA_CONCEPTS_VEGETATED_TERRAIN_TOOLTIP]Vegetated Terrain[/TIP] does not end Unit [icon:Action_Move] Movement.', '|FEATURE_CLASS_VEGETATED|', 2, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_HATSHEPSUT__AGENDA', 'LEADER_HATSHEPSUT', 'TRAIT_LEADER_HATSHEPSUT_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 0, 0, NULL, NULL),
  ('LEADER_HATSHEPSUT__B01', 'LEADER_HATSHEPSUT', 'TRAIT_LEADER_HATSHEPSUT_ABILITY', 'bullet', 1, 1, NULL, '+1 [icon:YIELD_CULTURE] Culture per [TIP:LOC_PEDIA_CONCEPTS_AGE_TOOLTIP]Age[/TIP] for every unique [icon:RADIAL_RESOURCES] [TIP:LOC_PEDIA_CONCEPTS_RESOURCES_TOOLTIP]Resource[/TIP].', NULL, 3, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_HATSHEPSUT__B02', 'LEADER_HATSHEPSUT', 'TRAIT_LEADER_HATSHEPSUT_ABILITY', 'bullet', 2, 1, NULL, '+15% [icon:YIELD_PRODUCTION] Production towards constructing [icon:CITY_BUILDING_LIST] [TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Buildings[/TIP] and [icon:WONDER] [TIP:LOC_PEDIA_CONCEPTS_WONDERS_TOOLTIP]Wonders[/TIP] in [icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Cities[/TIP] adjacent to [TIP:LOC_PEDIA_CONCEPTS_NAVIGABLE_RIVER_TOOLTIP]Navigable Rivers[/TIP].', '|TERRAIN_NAVIGABLE_RIVER|', 4, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_HIMIKO_ALT__AGENDA', 'LEADER_HIMIKO_ALT', 'TRAIT_LEADER_HIMIKO_ALT_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 0, 0, NULL, NULL),
  ('LEADER_HIMIKO_ALT__B01', 'LEADER_HIMIKO_ALT', 'TRAIT_LEADER_HIMIKO_ALT_ABILITY', 'bullet', 1, 1, NULL, '[B]+2 [icon:YIELD_HAPPINESS] Happiness [/B]per Age on [icon:YIELD_HAPPINESS] [B]Happiness [/B]and [icon:YIELD_DIPLOMACY] [B]Diplomacy Buildings[/B], doubled if a [B]Building[/B] is both.', NULL, 3, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_HIMIKO_ALT__B02', 'LEADER_HIMIKO_ALT', 'TRAIT_LEADER_HIMIKO_ALT_ABILITY', 'bullet', 2, 1, NULL, '[B]+50% [icon:YIELD_PRODUCTION] Production [/B]towards constructing [icon:YIELD_HAPPINESS] [B]Happiness[/B] and [icon:YIELD_DIPLOMACY] [B]Diplomacy Buildings[/B], doubled if a [B]Building[/B] is both.', NULL, 2, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_HIMIKO_ALT__B03', 'LEADER_HIMIKO_ALT', 'TRAIT_LEADER_HIMIKO_ALT_ABILITY', 'bullet', 3, 1, NULL, '[B]+15% [icon:YIELD_CULTURE] Culture [/B]but [B]-15% [icon:YIELD_SCIENCE] Science[/B], and these effects are [B]doubled [/B]while in a [icon:CELEBRATION] [B]Celebration[/B].[/LIST]', NULL, 3, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_HIMIKO__AGENDA', 'LEADER_HIMIKO', 'TRAIT_LEADER_HIMIKO_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 0, 0, NULL, NULL),
  ('LEADER_HIMIKO__B01', 'LEADER_HIMIKO', 'TRAIT_LEADER_HIMIKO_ABILITY', 'bullet', 1, 1, NULL, 'Gain a unique [icon:ENDEAVOR] [TIP:LOC_PEDIA_CONCEPTS_ENDEAVOR_TOOLTIP]Endeavor[/TIP] called Friend of Wei that can be performed in an [icon:PLAYER_RELATIONSHIP_ALLIANCE] [TIP:LOC_PEDIA_CONCEPTS_ALLIANCE_TOOLTIP]Alliance[/TIP] to grant you and your ally +25% [icon:YIELD_SCIENCE] Science.', NULL, 3, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_HIMIKO__B02', 'LEADER_HIMIKO', 'TRAIT_LEADER_HIMIKO_ABILITY', 'bullet', 2, 1, NULL, '+4 [icon:YIELD_SCIENCE] Science per [TIP:LOC_PEDIA_CONCEPTS_AGE_TOOLTIP]Age[/TIP] for every Leader you are [icon:PLAYER_RELATIONSHIP_FRIENDLY] Friendly or [icon:PLAYER_RELATIONSHIP_HELPFUL] Helpful with.', NULL, 3, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_HIMIKO__B03', 'LEADER_HIMIKO', 'TRAIT_LEADER_HIMIKO_ABILITY', 'bullet', 3, 1, NULL, 'Can Support [icon:ENDEAVOR] [TIP:LOC_PEDIA_CONCEPTS_ENDEAVOR_TOOLTIP]Endeavors[/TIP] for free, but Rejecting [icon:DIPLOMATIC_ACTION] Diplomatic Actions costs +100% [icon:YIELD_DIPLOMACY] Influence.', NULL, 2, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_Hiro__B01', 'LEADER_Hiro', 'TRAIT_LEADER_Hiro_ABILITY', 'bullet', 1, 1, NULL, '[B]Death Rewind:[/B][icon:UNIT_RANGED_CLASS]Ranged units and [icon:UNIT_ARMY_COMMANDER]Army Commanders gain [B]1[/B] respawn charge, respawning with [B]1%[/B] health. [icon:UNIT_ARMY_COMMANDER]Commander respawn time [B]-75%[/B].', NULL, 3, '|UNIT_CLASS_RANGED|UNIT_CLASS_COMMAND|', 1, 1, 1, 1, 'MAO-Leader-MahoShojoWitchTrial', NULL),
  ('LEADER_Hiro__B02', 'LEADER_Hiro', 'TRAIT_LEADER_Hiro_ABILITY', 'bullet', 2, 1, NULL, '[B]Justice Verdict:[/B][B]+1[/B][icon:WAR_SUPPORT]War Support when declaring [icon:WAR]War. [B]+30%[/B] [icon:YIELD_DIPLOMACY]Influence efficiency towards adding [icon:WAR_SUPPORT]War Support.', NULL, 2, NULL, 1, 1, 1, 1, 'MAO-Leader-MahoShojoWitchTrial', NULL),
  ('LEADER_Hiro__B03', 'LEADER_Hiro', 'TRAIT_LEADER_Hiro_ABILITY', 'bullet', 3, 1, NULL, '[B]Triumph Legacy:[/B] Each completed [B]major Triumph[/B] gives your [B]Capital[/B] [B]+10%[/B] to that [B]Attribute[/B]''s yield ([B]stacks[/B] on the same Attribute, [B]current Age[/B] only).[/LIST][N]Special Diplomatic Actions: [icon:WITCH_TRIAL_PACT][B]Witch Trial Pact[/B] and [icon:WITCH_VERDICT][B]Witch Verdict[/B].', NULL, 3, NULL, 1, 1, 1, 1, 'MAO-Leader-MahoShojoWitchTrial', 'The text names Witch Trial Pact and Witch Verdict, but Hiro''s ability has no modifier that unlocks them.'),
  ('LEADER_Houraisan__AGENDA', 'LEADER_Houraisan', 'TRAIT_LEADER_Houraisan_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 0, 1, 'MAO-Leader-Houraisan', NULL),
  ('LEADER_Houraisan__B01', 'LEADER_Houraisan', 'TRAIT_LEADER_Houraisan_ABILITY', 'bullet', 1, 1, NULL, '[B]Eternal Blessing:[/B] All [icon:YIELD_CITIES]cities gain [B]+15%[/B] [icon:YIELD_FOOD]Food and [B]+10%[/B] [icon:YIELD_HAPPINESS]Happiness. Districts on [icon:CITY_UNIMPROVED]vegetated terrain do not remove the tile''s [B]natural yields[/B], and gain [B]+1[/B] [icon:YIELD_HAPPINESS]Happiness. All [B]Buildings[/B] gain [B]+1[/B] [icon:YIELD_FOOD]Food from adjacent [icon:RESOURCE_CLASS]Resources.', '|FEATURE_CLASS_VEGETATED|', 5, NULL, 1, 1, 1, 1, 'MAO-Leader-Houraisan', NULL),
  ('LEADER_Houraisan__B02', 'LEADER_Houraisan', 'TRAIT_LEADER_Houraisan_ABILITY', 'bullet', 2, 1, NULL, '[B]Forest of Hourai:[/B] Units gain [B]+3[/B] [icon:COMBAT_STRENGTH]Combat Strength when fighting on [icon:CITY_UNIMPROVED]vegetated terrain. [icon:Action_Showall]Vision can see through vegetation, and vegetated terrain does not consume unit [icon:Action_Move]Movement.', '|FEATURE_CLASS_VEGETATED|', 3, NULL, 1, 1, 1, 1, 'MAO-Leader-Houraisan', NULL),
  ('LEADER_Houraisan__B03', 'LEADER_Houraisan', 'TRAIT_LEADER_Houraisan_ABILITY', 'bullet', 3, 1, NULL, '[B]Five Impossible Requests:[/B] Unlock [B]five[/B] special [icon:DEFAULT_PROJECT]projects across three ages, each providing unique bonus effects.[/LIST][NEWLINE][I]"To live forever is to witness all of time." —Houraisan Kaguya[/I]', NULL, 3, '|PROJECT_BUDDHA_BOWL|PROJECT_JEWEL_BRANCH|PROJECT_FIRE_RAT_ROBE|PROJECT_DRAGON_JEWEL|PROJECT_SWALLOW_COWRY|', 1, 1, 1, 1, 'MAO-Leader-Houraisan', 'The projects are the mod''s own PROJECT_* rows; any requirement on them that names Kaguya would leave them unbuildable elsewhere. Not read.'),
  ('LEADER_IBN_BATTUTA__AGENDA', 'LEADER_IBN_BATTUTA', 'TRAIT_LEADER_IBN_BATTUTA_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 0, 0, NULL, NULL),
  ('LEADER_IBN_BATTUTA__B01', 'LEADER_IBN_BATTUTA', 'TRAIT_LEADER_IBN_BATTUTA_ABILITY', 'bullet', 1, 1, NULL, 'Gains 2 [icon:ATTRIBUTE_WILDCARD] [TIP:LOC_PEDIA_CONCEPTS_ATTRIBUTE_TOOLTIP]Wildcard Attribute[/TIP] Points after the first [icon:RADIAL_CIVICS] [TIP:LOC_PEDIA_CONCEPTS_CIVIC_TOOLTIP]Civic[/TIP] in every [TIP:LOC_PEDIA_CONCEPTS_AGE_TOOLTIP]Age[/TIP].', NULL, 3, NULL, 1, 1, 1, 0, NULL, 'IBN_BATTUTA_MOD_WILDCARD_ATTRIBUTE is EFFECT_DO_NOTHING. Nothing in the data or the game''s scripts grants the points, so the engine must key the grant to something else; whether another leader holding this modifier gets the points is a lab check.');
INSERT OR IGNORE INTO LShufMapping (PieceId, LeaderType, AbilityTrait, Kind, BulletIndex, BulletCount, BulletList, BulletText, BiasTags, Value, SpecificTo, Movable, Reviewed, Guess, IsModded, ModId, Note) VALUES
  ('LEADER_IBN_BATTUTA__B02', 'LEADER_IBN_BATTUTA', 'TRAIT_LEADER_IBN_BATTUTA_ABILITY', 'bullet', 2, 1, NULL, '+1 [icon:Action_Showall] [TIP:LOC_PEDIA_CONCEPTS_SIGHT_TOOLTIP]Sight[/TIP] for all Units.', NULL, 2, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_IBN_BATTUTA__B03', 'LEADER_IBN_BATTUTA', 'TRAIT_LEADER_IBN_BATTUTA_ABILITY', 'bullet', 3, 1, NULL, 'Gain a unique [icon:ENDEAVOR] [TIP:LOC_PEDIA_CONCEPTS_ENDEAVOR_TOOLTIP]Endeavor[/TIP] called Trade Maps that allows you to gradually see other Leaders'' claimed territory.', NULL, 2, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_ISABELLA__AGENDA', 'LEADER_ISABELLA', 'TRAIT_LEADER_ISABELLA_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 0, 0, NULL, NULL),
  ('LEADER_ISABELLA__B01', 'LEADER_ISABELLA', 'TRAIT_LEADER_ISABELLA_ABILITY', 'bullet', 1, 1, NULL, 'Gain 100 [icon:YIELD_GOLD] Gold per [TIP:LOC_PEDIA_CONCEPTS_AGE_TOOLTIP]Age[/TIP] every time you discover a [icon:NOTIFICATION_DISCOVER_NATURAL_WONDER] Natural Wonder. This is doubled if the Natural Wonder is in [TIP:LOC_PEDIA_CONCEPTS_DISTANT_LANDS_TOOLTIP]Distant Lands[/TIP].', '|NATURAL_WONDER|', 3, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_ISABELLA__B02', 'LEADER_ISABELLA', 'TRAIT_LEADER_ISABELLA_ABILITY', 'bullet', 2, 1, NULL, '+50% tile yields from [icon:NOTIFICATION_DISCOVER_NATURAL_WONDER] Natural Wonders for every Natural Wonder in your Empire.', '|NATURAL_WONDER|', 3, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_ISABELLA__B03', 'LEADER_ISABELLA', 'TRAIT_LEADER_ISABELLA_ABILITY', 'bullet', 3, 1, NULL, '+50% [icon:YIELD_GOLD] Gold towards purchasing [TIP:LOC_PEDIA_CONCEPTS_NAVAL_UNITS_TOOLTIP]Naval Units[/TIP].', '|COAST|', 2, '|UNIT_CLASS_NAVAL|', 1, 1, 1, 0, NULL, NULL),
  ('LEADER_ISABELLA__B04', 'LEADER_ISABELLA', 'TRAIT_LEADER_ISABELLA_ABILITY', 'bullet', 4, 1, NULL, '-1 [icon:YIELD_GOLD] Gold [TIP:LOC_PEDIA_CONCEPTS_MAINTENANCE_TOOLTIP]maintenance[/TIP] for [TIP:LOC_PEDIA_CONCEPTS_NAVAL_UNITS_TOOLTIP]Naval Units[/TIP].', '|COAST|', 1, '|UNIT_CLASS_NAVAL|', 1, 1, 1, 0, NULL, NULL),
  ('LEADER_JOSE_RIZAL__AGENDA', 'LEADER_JOSE_RIZAL', 'TRAIT_LEADER_JOSE_RIZAL_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 0, 0, NULL, NULL),
  ('LEADER_JOSE_RIZAL__B01', 'LEADER_JOSE_RIZAL', 'TRAIT_LEADER_JOSE_RIZAL_ABILITY', 'bullet', 1, 1, NULL, 'When gaining rewards from a [icon:NAR_REW_DEFAULT] Narrative Event, gain an additional 20 [icon:YIELD_CULTURE] Culture, [icon:YIELD_GOLD] Gold and [icon:YIELD_DIPLOMACY] Influence per [TIP:LOC_PEDIA_CONCEPTS_AGE_TOOLTIP]Age[/TIP].', NULL, 3, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_JOSE_RIZAL__B02', 'LEADER_JOSE_RIZAL', 'TRAIT_LEADER_JOSE_RIZAL_ABILITY', 'bullet', 2, 1, NULL, 'Has additional [icon:NAR_REW_DEFAULT] Narrative Events.', NULL, 2, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_JOSE_RIZAL__B03', 'LEADER_JOSE_RIZAL', 'TRAIT_LEADER_JOSE_RIZAL_ABILITY', 'bullet', 3, 1, NULL, '+50% [icon:CELEBRATION] [TIP:LOC_PEDIA_CONCEPTS_CELEBRATIONS_TOOLTIP]Celebration[/TIP] duration.', NULL, 2, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_JOSE_RIZAL__B04', 'LEADER_JOSE_RIZAL', 'TRAIT_LEADER_JOSE_RIZAL_ABILITY', 'bullet', 4, 1, NULL, '+50% [icon:YIELD_HAPPINESS] Happiness towards [icon:CELEBRATION] [TIP:LOC_PEDIA_CONCEPTS_CELEBRATIONS_TOOLTIP]Celebrations[/TIP].', NULL, 2, NULL, 1, 1, 1, 0, NULL, 'The modifier is a plain +50% Happiness yield with no celebration requirement. Check the bullet means the same thing.'),
  ('LEADER_KingofHeroes__AGENDA', 'LEADER_KingofHeroes', 'TRAIT_LEADER_KingofHeroes_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 0, 1, 'MAO-Leader-KingofHeroes', NULL),
  ('LEADER_KingofHeroes__B01', 'LEADER_KingofHeroes', 'TRAIT_LEADER_KingofHeroes_ABILITY', 'bullet', 1, 1, NULL, '[B]Gate of Babylon:[/B] When [icon:MILITARY] Combat Units resolve combat, defeating an enemy unit grants [icon:YIELD_GOLD] Gold equal to the defeated unit''s full [icon:NAR_REW_COMBAT] Combat Strength. [icon:RADIAL_RESOURCES] Resource tiles gain bonus yields by class: [icon:RESOURCECLASS_CITY] City Resources [B]+1[/B] [icon:YIELD_FOOD] Food, [icon:RESOURCECLASS_BONUS] Bonus Resources [B]+1[/B] [icon:YIELD_PRODUCTION] Production, [icon:RESOURCECLASS_EMPIRE] Empire Resources [B]+1[/B] [icon:YIELD_GOLD] Gold.[/LI][N][BLIST]', NULL, 4, '|UNIT_CLASS_COMBAT|', 1, 1, 1, 1, 'MAO-Leader-KingofHeroes', NULL),
  ('LEADER_KingofHeroes__B02', 'LEADER_KingofHeroes', 'TRAIT_LEADER_KingofHeroes_ABILITY', 'bullet', 2, 1, NULL, '[B]Majesty of the Hero King:[/B] Rejecting any [icon:DIPLOMATIC_ACTION] Diplomatic Action [B]greatly reduces[/B] the [icon:YIELD_DIPLOMACY] Influence required. [B]+1[/B] [icon:WAR_SUPPORT] War Support on [icon:WAR] Wars you declare as the aggressor. Gain [B]100[/B] [icon:YIELD_DIPLOMACY] Influence immediately when you conquer a Settlement (City or Town) (scales with [B]Age[/B] and Game Speed).[/LI][N][BLIST]', NULL, 3, NULL, 1, 1, 1, 1, 'MAO-Leader-KingofHeroes', NULL),
  ('LEADER_KingofHeroes__B03', 'LEADER_KingofHeroes', 'TRAIT_LEADER_KingofHeroes_ABILITY', 'bullet', 3, 1, NULL, '[B]The Oldest King:[/B] [icon:NOTIFICATION_SELECT_CAPITAL] Capital [B]+50%[/B] [icon:YIELD_DIPLOMACY] Influence.[/LI]', NULL, 3, NULL, 1, 1, 1, 1, 'MAO-Leader-KingofHeroes', NULL),
  ('LEADER_Koishi__AGENDA', 'LEADER_Koishi', 'TRAIT_LEADER_KOISHI_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 0, 1, 'MAO-Leader-Koishi', NULL),
  ('LEADER_Koishi__B01', 'LEADER_Koishi', 'TRAIT_LEADER_KOISHI_ABILITY', 'bullet', 1, 1, NULL, '[B]Rose of Unconscious[/B]: All [B]Land Units[/B] can [B]freely enter[/B] foreign territory ignoring borders, and gain [icon:Action_Showall][B]Stealth[/B], visible only to adjacent enemy units.[/LI][N][BLIST]', NULL, 3, NULL, 1, 1, 1, 1, 'MAO-Leader-Koishi', NULL),
  ('LEADER_Koishi__B02', 'LEADER_Koishi', 'TRAIT_LEADER_KOISHI_ABILITY', 'bullet', 2, 1, NULL, '[B]Embryo''s Dream[/B]: Enemy civilizations [B]cannot[/B] use [icon:ESPIONAGE][B]Counter Spy[/B] against you; may declare [icon:WAR][B]Formal War[/B] [B]ignoring relationship requirements[/B].[/LI][N][BLIST]', NULL, 2, NULL, 1, 1, 1, 1, 'MAO-Leader-Koishi', NULL),
  ('LEADER_Koishi__B03', 'LEADER_Koishi', 'TRAIT_LEADER_KOISHI_ABILITY', 'bullet', 3, 1, NULL, '[B]Boundary of Recollection[/B]: All [B]diplomatic actions[/B] (support, oppose, sanctions, etc.) produce [B]no[/B] relationship changes; [B]Supporting[/B] or [B]Opposing[/B] [icon:ENDEAVOR]Endeavors costs [B]no[/B] [icon:YIELD_DIPLOMACY][B]Influence[/B].[/LI]', NULL, 2, NULL, 1, 1, 1, 1, 'MAO-Leader-Koishi', NULL),
  ('LEADER_LAFAYETTE__AGENDA', 'LEADER_LAFAYETTE', 'TRAIT_LEADER_LAFAYETTE_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 0, 0, NULL, NULL),
  ('LEADER_LAFAYETTE__B01', 'LEADER_LAFAYETTE', 'TRAIT_LEADER_LAFAYETTE_ABILITY', 'bullet', 1, 1, NULL, 'Gains a unique [icon:ENDEAVOR] [TIP:LOC_PEDIA_CONCEPTS_ENDEAVOR_TOOLTIP]Endeavor[/TIP] called Reform, which grants an additional [icon:NAR_REW_TRADITION_SLOT] [TIP:LOC_PEDIA_CONCEPTS_TRADITION_TOOLTIP]Tradition[/TIP] slot. Supporting this [TIP:LOC_PEDIA_CONCEPTS_ENDEAVOR_TOOLTIP]Endeavor[/TIP] also grants the other Leader an additional [TIP:LOC_PEDIA_CONCEPTS_TRADITION_TOOLTIP]Tradition[/TIP] slot, otherwise they are granted a [TIP:LOC_PEDIA_CONCEPTS_SOCIAL_POLICY_TOOLTIP]Social Policy[/TIP] slot. Reform is usable once with each other Leader.', NULL, 4, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_LAFAYETTE__B02', 'LEADER_LAFAYETTE', 'TRAIT_LEADER_LAFAYETTE_ABILITY', 'bullet', 2, 1, NULL, '+1 [icon:NAR_REW_COMBAT] [TIP:LOC_PEDIA_CONCEPTS_COMBAT_STRENGTH_TOOLTIP]Combat Strength[/TIP] for every [icon:TRADITION] [TIP:LOC_PEDIA_CONCEPTS_TRADITION_TOOLTIP]Tradition[/TIP], but not [icon:SOCIAL_POLICY] [TIP:LOC_PEDIA_CONCEPTS_SOCIAL_POLICY_TOOLTIP]Social Policy[/TIP], slotted in the [icon:GOVERNMENT] Government.', NULL, 2, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_LAFAYETTE__B03', 'LEADER_LAFAYETTE', 'TRAIT_LEADER_LAFAYETTE_ABILITY', 'bullet', 3, 1, NULL, '+1 [icon:YIELD_CULTURE] Culture and [icon:YIELD_HAPPINESS] Happiness per [TIP:LOC_PEDIA_CONCEPTS_AGE_TOOLTIP]Age[/TIP] in [TIP:LOC_PEDIA_CONCEPTS_SETTLEMENT_TOOLTIP]Settlements[/TIP], doubled in [TIP:LOC_PEDIA_CONCEPTS_DISTANT_LANDS_TOOLTIP]Distant Lands[/TIP].', '|COAST|', 3, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_LAKSHMIBAI__AGENDA', 'LEADER_LAKSHMIBAI', 'TRAIT_LEADER_LAKSHMIBAI_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 0, 0, NULL, NULL),
  ('LEADER_LAKSHMIBAI__B01', 'LEADER_LAKSHMIBAI', 'TRAIT_LEADER_LAKSHMIBAI_ABILITY', 'bullet', 1, 1, NULL, '[B]+50% [icon:YIELD_DIPLOMACY] Influence [/B]towards initiating the [icon:PROJECT] [B]City-State - Incorporate[/B] Action.', NULL, 2, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_LAKSHMIBAI__B02', 'LEADER_LAKSHMIBAI', 'TRAIT_LEADER_LAKSHMIBAI_ABILITY', 'bullet', 2, 1, NULL, 'When you incorporate a [icon:CITYSTATE] [B][TIP:LOC_PEDIA_CONCEPTS_CITY_STATE_TOOLTIP]City-State[/TIP] [/B], you gain all of their Units.', NULL, 2, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_LAKSHMIBAI__B03', 'LEADER_LAKSHMIBAI', 'TRAIT_LEADER_LAKSHMIBAI_ABILITY', 'bullet', 3, 1, NULL, 'When one of your [B]Land Military Units [/B]defeats an enemy Unit, gain [icon:YIELD_DIPLOMACY] [B]Influence [/B]equal to [B]100% [/B]of the defeated Unit''s [icon:NAR_REW_COMBAT] [B]Combat Strength[/B].[/LIST]', NULL, 3, '|UNIT_CLASS_COMBAT|', 1, 1, 1, 0, NULL, NULL),
  ('LEADER_MACHIAVELLI__AGENDA', 'LEADER_MACHIAVELLI', 'TRAIT_LEADER_MACHIAVELLI_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 0, 0, NULL, NULL),
  ('LEADER_MACHIAVELLI__B01', 'LEADER_MACHIAVELLI', 'TRAIT_LEADER_MACHIAVELLI_ABILITY', 'bullet', 1, 1, NULL, '+3 [icon:YIELD_DIPLOMACY] Influence per [TIP:LOC_PEDIA_CONCEPTS_AGE_TOOLTIP]Age[/TIP].', NULL, 3, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_MACHIAVELLI__B02', 'LEADER_MACHIAVELLI', 'TRAIT_LEADER_MACHIAVELLI_ABILITY', 'bullet', 2, 1, NULL, 'Gains 50 [icon:YIELD_GOLD] Gold per [TIP:LOC_PEDIA_CONCEPTS_AGE_TOOLTIP]Age[/TIP] when your [icon:DIPLOMATIC_ACTION] Diplomatic Action proposals are accepted, or 100 [icon:YIELD_GOLD] Gold when they are rejected.', NULL, 3, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_MACHIAVELLI__B03', 'LEADER_MACHIAVELLI', 'TRAIT_LEADER_MACHIAVELLI_ABILITY', 'bullet', 3, 1, NULL, 'Ignores [icon:RELATIONSHIP] Relationship requirements for declaring [icon:WAR] Formal Wars.', NULL, 2, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_MACHIAVELLI__B04', 'LEADER_MACHIAVELLI', 'TRAIT_LEADER_MACHIAVELLI_ABILITY', 'bullet', 4, 1, NULL, 'Can Levy Troops from [icon:CITYSTATE] [TIP:LOC_PEDIA_CONCEPTS_CITY_STATE_TOOLTIP]City-States[/TIP] you are not [TIP:LOC_PEDIA_CONCEPTS_SUZERAIN_TOOLTIP]Suzerain[/TIP] of.', NULL, 2, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_MAOZEDONG__B01', 'LEADER_MAOZEDONG', 'TRAIT_LEADER_MAOZEDONG_ABILITY', 'bullet', 1, 1, NULL, '[B][icon:CITY_BUILDING_LIST]Building[/B] and [B][icon:SPECIALIST]Specialist[/B] maintenance efficiency +25%. [B][icon:YIELD_CITIES]Cities[/B] gain +2 [B][icon:YIELD_PRODUCTION]Production[/B] for [B]each connected settlement[/B], scaling with era.', NULL, 4, NULL, 1, 1, 1, 1, 'Mao Zedong', NULL),
  ('LEADER_MAOZEDONG__B02', 'LEADER_MAOZEDONG', 'TRAIT_LEADER_MAOZEDONG_ABILITY', 'bullet', 2, 1, NULL, 'During peacetime, each [B]district population[/B] in settlements provides +0.5 [B][icon:YIELD_PRODUCTION]Production[/B], and each [B]rural population[/B] provides +0.5 [B][icon:YIELD_FOOD]Food[/B], scaling with era. [B][icon:YIELD_TOWNS]Towns[/B] gain +15% [B][icon:GROWTH_RATE]Development Rate[/B], and [B]specialized towns[/B] gain +15% [B]Yields[/B].', NULL, 4, NULL, 1, 1, 1, 1, 'Mao Zedong', 'MAOZEDONG_MOD_ABILITY3 (rural Food) has no peace requirement, unlike the text.'),
  ('LEADER_MAOZEDONG__B03', 'LEADER_MAOZEDONG', 'TRAIT_LEADER_MAOZEDONG_ABILITY', 'bullet', 3, 1, NULL, 'During wartime,+100% efficiency when [B]purchase and production units[/B].Units gain +1 [B][icon:Action_Move]Movement[/B] and [B]ignore Zone of Control[/B].[/LIST]', NULL, 3, NULL, 1, 1, 1, 1, 'Mao Zedong', NULL),
  ('LEADER_MAO_Astolfo__AGENDA', 'LEADER_MAO_Astolfo', 'TRAIT_LEADER_MAO_Astolfo_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 0, 1, 'MAO-Leader-MAO_Astolfo', NULL),
  ('LEADER_MAO_Astolfo__B01', 'LEADER_MAO_Astolfo', 'TRAIT_LEADER_MAO_Astolfo_ABILITY', 'bullet', 1, 1, NULL, '[B]Evaporation of Reason (Saber):[/B] City [icon:YIELD_SCIENCE]Science and [icon:YIELD_CULTURE]Culture output is reduced by [B]-99%[/B]. All cities gain [B]+20%[/B] [icon:YIELD_HAPPINESS]Happiness. [B]60%[/B] of your total Happiness is directly added as global [icon:YIELD_SCIENCE]Science and [icon:YIELD_CULTURE]Culture. (AI: Only +20% Happiness, no penalties or conversion)', NULL, 3, NULL, 1, 1, 1, 1, 'MAO-Leader-MAO_Astolfo', NULL),
  ('LEADER_MAO_Astolfo__B02', 'LEADER_MAO_Astolfo', 'TRAIT_LEADER_MAO_Astolfo_ABILITY', 'bullet', 2, 1, NULL, '[B]Grandiose Triumphant Return:[/B] [icon:UNIT_STRENGTH]Melee units gain [B]+3[/B] Combat Strength. Each melee unit provides [B]+2[/B] [icon:YIELD_HAPPINESS]Happiness.', NULL, 2, '|UNIT_CLASS_MELEE|', 1, 1, 1, 1, 'MAO-Leader-MAO_Astolfo', NULL),
  ('LEADER_MAO_Tanya__AGENDA', 'LEADER_MAO_Tanya', 'TRAIT_LEADER_MAO_Tanya_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 0, 1, 'MAO-Leader-MAO_Tanya', NULL);
INSERT OR IGNORE INTO LShufMapping (PieceId, LeaderType, AbilityTrait, Kind, BulletIndex, BulletCount, BulletList, BulletText, BiasTags, Value, SpecificTo, Movable, Reviewed, Guess, IsModded, ModId, Note) VALUES
  ('LEADER_MAO_Tanya__B01', 'LEADER_MAO_Tanya', 'TRAIT_LEADER_MAO_Tanya_ABILITY', 'bullet', 1, 1, NULL, '[B]Mage Technology:[/B] When at [icon:WAR]war, all Military Commanders gain [B]Flight Gear[/B] — they can traverse and stop on Mountains.', '|TERRAIN_MOUNTAIN|', 2, NULL, 1, 1, 1, 1, 'MAO-Leader-MAO_Tanya', NULL),
  ('LEADER_MAO_Tanya__B02', 'LEADER_MAO_Tanya', 'TRAIT_LEADER_MAO_Tanya_ABILITY', 'bullet', 2, 1, NULL, '[B]Iron Discipline:[/B] All Military Commanders start with the [icon:COMMENDATION][B]Duty Commendation[/B] (Hero Attack). All military units gain up to [B]+6[/B][icon:NAR_REW_COMBAT] defense at low [icon:DAMAGED]HP.', NULL, 3, '|UNIT_CLASS_ARMY_COMMANDER|', 1, 1, 1, 1, 'MAO-Leader-MAO_Tanya', NULL),
  ('LEADER_MAO_Tanya__B03', 'LEADER_MAO_Tanya', 'TRAIT_LEADER_MAO_Tanya_ABILITY', 'bullet', 3, 1, NULL, '[B]War Economy:[/B] Each ongoing [icon:WAR]war grants all cities [B]+10%[/B][icon:YIELD_GOLD] Gold and [B]+20%[/B][icon:YIELD_PRODUCTION] Unit Training Efficiency (up to [B]+50%/100%[/B]).', NULL, 3, NULL, 1, 1, 1, 1, 'MAO-Leader-MAO_Tanya', NULL),
  ('LEADER_Margatroid__AGENDA', 'LEADER_Margatroid', 'TRAIT_LEADER_MARGATROID_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 0, 1, 'MAO-Leader-Margatroid', NULL),
  ('LEADER_Margatroid__B01', 'LEADER_Margatroid', 'TRAIT_LEADER_MARGATROID_ABILITY', 'bullet', 1, 1, NULL, '[B]Doll Workshop:[/B] Each adjacent [B]Woodcutter[/B] provides [icon:CITY_BUILDING_LIST][B]Buildings[/B] with [B]+1[/B][icon:YIELD_PRODUCTION] [B]Production[/B]. [B]+50%[/B][icon:YIELD_PRODUCTION] Production towards [icon:YIELD_PRODUCTION][B]Production Buildings[/B].', NULL, 3, '|IMPROVEMENT_WOODCUTTER|', 1, 1, 1, 1, 'MAO-Leader-Margatroid', NULL),
  ('LEADER_Margatroid__B02', 'LEADER_Margatroid', 'TRAIT_LEADER_MARGATROID_ABILITY', 'bullet', 2, 1, NULL, '[B]Puppeteer:[/B] [icon:UNIT_ARMY_COMMANDER][B]Army Commanders[/B] start with the [B]Valor Commendation[/B] (grants [B]"Second Chance"[/B] ability). [icon:CITY_UNIMPROVED]Vegetated Terrain does not end Commander [icon:Action_Move]Movement. Units in [icon:UNIT_ARMY_COMMANDER][B]Commander Formation[/B] gain [B]+10[/B][icon:Action_Heal] Healing per turn.[/LIST][N][I]"Leave it to the dolls."—Alice Margatroid[/I]', '|FEATURE_CLASS_VEGETATED|', 3, '|UNIT_CLASS_ARMY_COMMANDER|', 1, 1, 1, 1, 'MAO-Leader-Margatroid', NULL),
  ('LEADER_NAPOLEON_ALT__AGENDA', 'LEADER_NAPOLEON_ALT', 'TRAIT_LEADER_NAPOLEON_ALT_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 0, 0, NULL, NULL),
  ('LEADER_NAPOLEON_ALT__B01', 'LEADER_NAPOLEON_ALT', 'TRAIT_LEADER_NAPOLEON_ALT_ABILITY', 'bullet', 1, 1, NULL, '[B]+1 [icon:Action_Move] Movement [/B]for all [B]Land Units[/B].', NULL, 4, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_NAPOLEON_ALT__B02', 'LEADER_NAPOLEON_ALT', 'TRAIT_LEADER_NAPOLEON_ALT_ABILITY', 'bullet', 2, 1, NULL, 'Defeating an enemy Unit provides [icon:YIELD_CULTURE] [B]Culture [/B]equal to [B]100% [/B]of its [icon:NAR_REW_COMBAT] [B]Combat Strength[/B].', NULL, 3, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_NAPOLEON_ALT__B03', 'LEADER_NAPOLEON_ALT', 'TRAIT_LEADER_NAPOLEON_ALT_ABILITY', 'bullet', 3, 1, NULL, 'The first time each Age that a [icon:WAR] [B]War[/B] is declared against you, gain an [icon:UNIT_ARMY_COMMANDER] [B]Army Commander[/B] in your [icon:NOTIFICATION_SELECT_CAPITAL] [B] Capital[/B] packed with [B]1 Infantry Unit, 1 Cavalry Unit, 1 Ranged Unit, and 1 Siege Unit[/B], even if those Units have not been unlocked.[/LIST]', NULL, 3, '|UNIT_ARMY_COMMANDER|UNIT_CLASS_INFANTRY|UNIT_CLASS_RANGED|UNIT_CLASS_SIEGE|UNIT_CLASS_CAVALRY|', 1, 1, 1, 0, NULL, NULL),
  ('LEADER_NAPOLEON__AGENDA', 'LEADER_NAPOLEON', 'TRAIT_LEADER_NAPOLEON_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 0, 0, NULL, NULL),
  ('LEADER_NAPOLEON__B01', 'LEADER_NAPOLEON', 'TRAIT_LEADER_NAPOLEON_ABILITY', 'bullet', 1, 1, NULL, 'All basic [icon:SANCTIONS] [B]Sanctions [/B]are automatically unlocked.', NULL, 2, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_NAPOLEON__B02', 'LEADER_NAPOLEON', 'TRAIT_LEADER_NAPOLEON_ABILITY', 'bullet', 2, 1, NULL, '[B]+50% [icon:DIPLOMACY]Influence [/B]towards initiating [icon:SANCTIONS][B] Sanctions[/B].', NULL, 2, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_NAPOLEON__B03', 'LEADER_NAPOLEON', 'TRAIT_LEADER_NAPOLEON_ABILITY', 'bullet', 3, 1, NULL, '[B]+5 [icon:YIELD_CULTURE] Culture and [icon:YIELD_GOLD] Gold per Age [/B]for each Leader you have an active [B][icon:SANCTIONS] Sanction [/B]on, except [B] Denouncement [/B].', NULL, 3, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_NAPOLEON__B04', 'LEADER_NAPOLEON', 'TRAIT_LEADER_NAPOLEON_ABILITY', 'bullet', 4, 1, NULL, '[B]+1 [icon:NAR_REW_COMBAT] Combat Strength [/B]for [B]Land Units [/B]for every [icon:SANCTIONS][B] Sanction [/B]you have active, except [B]Denouncement[/B].[/LIST]', NULL, 2, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_Nearl__AGENDA', 'LEADER_Nearl', 'TRAIT_LEADER_NEARL_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 0, 1, 'MAO-Leader-Nearl', NULL),
  ('LEADER_Nearl__B01', 'LEADER_Nearl', 'TRAIT_LEADER_NEARL_ABILITY', 'bullet', 1, 1, NULL, '[icon:YIELD_DIPLOMACY][B]Pegasus Aura:[/B] When you win combat in your territory, gain [icon:YIELD_DIPLOMACY][B]Influence[/B] equal to 100% of the defeated unit''s production cost; [icon:UNIT_CAVALRY][B]Cavalry Units[/B] extend this effect to combat outside your territory.', NULL, 3, '|UNIT_CLASS_CAVALRY|', 1, 1, 1, 1, 'MAO-Leader-Nearl', NULL),
  ('LEADER_Nearl__B02', 'LEADER_Nearl', 'TRAIT_LEADER_NEARL_ABILITY', 'bullet', 2, 1, NULL, '[icon:CITY_DEFENSE][B]Guardian''s Oath:[/B] Cities with [icon:Action_Fortify]garrisoned units gain [icon:YIELD_HAPPINESS][B]+2 Happiness[/B]; [icon:Action_Fortify][B]Garrisoned units[/B] gain [icon:NAR_REW_COMBAT][B]+5 Combat Strength[/B].', NULL, 2, NULL, 1, 1, 1, 1, 'MAO-Leader-Nearl', NULL),
  ('LEADER_Nearl__B03', 'LEADER_Nearl', 'TRAIT_LEADER_NEARL_ABILITY', 'bullet', 3, 1, NULL, '[icon:NAR_REW_COMBAT][B]Defender Operator:[/B] Gain [icon:NAR_REW_COMBAT][B]+5 Combat Strength[/B] while defending.[/LIST]', NULL, 3, NULL, 1, 1, 1, 1, 'MAO-Leader-Nearl', NULL),
  ('LEADER_ODA_NOBUNAGA__AGENDA', 'LEADER_ODA_NOBUNAGA', 'TRAIT_LEADER_ODA_NOBUNAGA_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 0, 1, 'MAO_ODA_NOBUNAGA', NULL),
  ('LEADER_ODA_NOBUNAGA__B01', 'LEADER_ODA_NOBUNAGA', 'TRAIT_LEADER_ODA_NOBUNAGA_ABILITY', 'bullet', 1, 1, NULL, '[B]Demon King of the Sixth Heaven: [/B][B]Land military units[/B] gain [B]+4[/B] [icon:STAT_COMBAT_STRENGTH] Combat Strength when [B]defending[/B] while adjacent to a [B]Siege unit[/B]. [icon:UNIT_CLASS_SIEGE][B]Land Siege units[/B] adjacent to a friendly [B]Army Commander[/B] gain [B]+1[/B] [icon:Action_Ranged] Range and [B]+3[/B] [icon:NAR_REW_COMBAT] Bombard Strength (stacked units excluded).', NULL, 3, '|UNIT_CLASS_SIEGE|UNIT_CLASS_COMBAT|UNIT_CLASS_ARMY_COMMANDER|', 1, 1, 1, 1, 'MAO_ODA_NOBUNAGA', NULL),
  ('LEADER_ODA_NOBUNAGA__B02', 'LEADER_ODA_NOBUNAGA', 'TRAIT_LEADER_ODA_NOBUNAGA_ABILITY', 'bullet', 2, 1, NULL, '[B]Rakuichi-Rakuza: [/B][icon:YIELD_GOLD]Purchasing [icon:YIELD_PRODUCTION][B]Production Buildings[/B] costs [B]+40%[/B] [icon:YIELD_GOLD] Gold efficiency. Constructing [icon:YIELD_GOLD][B]Gold Buildings[/B] gains [B]+40%[/B] [icon:YIELD_PRODUCTION] Production efficiency.', NULL, 2, NULL, 1, 1, 1, 1, 'MAO_ODA_NOBUNAGA', NULL),
  ('LEADER_ODA_NOBUNAGA__B03', 'LEADER_ODA_NOBUNAGA', 'TRAIT_LEADER_ODA_NOBUNAGA_ABILITY', 'bullet', 3, 1, NULL, '[B]Tenka Fubu: [/B][icon:BUILDING_TEMPLE][B]Temples[/B] provide [B]-5[/B] [icon:YIELD_HAPPINESS] Happiness. Each [icon:UNIT_CLASS_COMBAT][B]Land military unit[/B] provides [B]+1[/B] [icon:YIELD_HAPPINESS] Happiness.', NULL, 2, '|BUILDING_ALTAR|UNIT_CLASS_COMBAT|', 1, 1, 1, 1, 'MAO_ODA_NOBUNAGA', NULL),
  ('LEADER_OKITA_SOUJI__AGENDA', 'LEADER_OKITA_SOUJI', 'TRAIT_LEADER_OKITA_SOUJI_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 0, 1, 'MAO-Leader-OKITA_SOUJI', NULL),
  ('LEADER_OKITA_SOUJI__B01', 'LEADER_OKITA_SOUJI', 'TRAIT_LEADER_OKITA_SOUJI_ABILITY', 'bullet', 1, 1, NULL, '[B]Sandanzuki[/B]: [icon:NAR_REW_COMBAT]Gain [B]Combat Strength[/B] when attacking wounded enemies based on their damage (1%→[B]+3[/B], 25%→[B]+4[/B], 50%→[B]+5[/B], 75%→[B]+6[/B]). Additionally, [B]flanking bonuses[/B] are [B]doubled[/B] when [B]attacking[/B].[/LI][N][BLIST]', NULL, 3, NULL, 1, 1, 1, 1, 'MAO-Leader-OKITA_SOUJI', NULL),
  ('LEADER_OKITA_SOUJI__B02', 'LEADER_OKITA_SOUJI', 'TRAIT_LEADER_OKITA_SOUJI_ABILITY', 'bullet', 2, 1, NULL, '[B]Banner of Makoto[/B]: Each [B]Infantry[/B] unit provides [B]+1[/B] [icon:YIELD_CULTURE][B]Culture[/B] (scales with [B]Age[/B]).[/LI][N][BLIST]', NULL, 2, '|UNIT_CLASS_INFANTRY|', 1, 1, 1, 1, 'MAO-Leader-OKITA_SOUJI', NULL),
  ('LEADER_OKITA_SOUJI__B03', 'LEADER_OKITA_SOUJI', 'TRAIT_LEADER_OKITA_SOUJI_ABILITY', 'bullet', 3, 1, NULL, '[B]First Unit Captain[/B]: [icon:UNIT_ARMY_COMMANDER][B]Military Commanders[/B] gain [B]+30%[/B] experience. All [B]Military Commanders[/B] provide [B]+10[/B], [B]+5%[/B] [icon:YIELD_HAPPINESS][B]Happiness[/B], and [B]+20%[/B] [B]Military Unit[/B] training speed to their city.[/LI]', NULL, 3, '|UNIT_CLASS_COMMAND|UNIT_CLASS_COMBAT|', 1, 1, 1, 1, 'MAO-Leader-OKITA_SOUJI', NULL),
  ('LEADER_OLGA__AGENDA', 'LEADER_OLGA', 'TRAIT_LEADER_OLGA_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 0, 1, 'MAO-Leader-OLGA', NULL),
  ('LEADER_OLGA__B01', 'LEADER_OLGA', 'TRAIT_LEADER_OLGA_ABILITY', 'bullet', 1, 1, NULL, '[B]Director of Chaldea[/B]: Unlocks [icon:DIPLOMATIC_ACTION][B]Exchange Map[/B], allowing insight into territories explored by other leaders. [B]Breathtaking[/B] tiles in your [B]Capital[/B] grant [B]+1[/B][icon:YIELD_SCIENCE][B]Science[/B]; [B]Breathtaking[/B] tiles outside your [B]Capital[/B] grant [B]+1[/B][icon:YIELD_HAPPINESS][B]Happiness[/B].[/LI][N][BLIST]', NULL, 3, NULL, 1, 1, 1, 1, 'MAO-Leader-OLGA', NULL),
  ('LEADER_OLGA__B02', 'LEADER_OLGA', 'TRAIT_LEADER_OLGA_ABILITY', 'bullet', 2, 1, NULL, '[B]SHEBA - Near-Future Observation Lens[/B]: [icon:FEATURE_NATURAL_WONDER][B]Natural Wonder[/B] tiles yield [B]+50%[/B]. [icon:NOTIFICATION_DISCOVER_NATURAL_WONDER]Discovering a [B]Natural Wonder[/B] grants [B]+50[/B][icon:YIELD_SCIENCE][B]Science[/B], [B]+50[/B][icon:YIELD_CULTURE][B]Culture[/B] (scales each Age), and [B]+1[/B][icon:ATTRIBUTE_WILDCARD][B]Wildcard Attribute Point[/B].[/LI][N][BLIST]', '|NATURAL_WONDER|', 3, NULL, 1, 1, 1, 1, 'MAO-Leader-OLGA', NULL),
  ('LEADER_OLGA__B03', 'LEADER_OLGA', 'TRAIT_LEADER_OLGA_ABILITY', 'bullet', 3, 1, NULL, '[B]Human Order Preservation Mission[/B]: [icon:NOTIFICATION_DECLARE_WAR]Defensive Wars grant [B]+2[/B][icon:WAR_SUPPORT][B]War Support[/B].[/LI]', NULL, 1, NULL, 1, 1, 1, 1, 'MAO-Leader-OLGA', NULL),
  ('LEADER_PACHACUTI__AGENDA', 'LEADER_PACHACUTI', 'TRAIT_LEADER_PACHACUTI_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 0, 0, NULL, NULL),
  ('LEADER_PACHACUTI__B01', 'LEADER_PACHACUTI', 'TRAIT_LEADER_PACHACUTI_ABILITY', 'bullet', 1, 1, NULL, 'All [icon:CITY_BUILDING_LIST] [TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Buildings[/TIP] receive a +1 [icon:YIELD_FOOD] Food Adjacency for Mountains.', '|TERRAIN_MOUNTAIN|', 3, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_PACHACUTI__B02', 'LEADER_PACHACUTI', 'TRAIT_LEADER_PACHACUTI_ABILITY', 'bullet', 2, 1, NULL, '-2 [icon:YIELD_HAPPINESS] [TIP:LOC_PEDIA_CONCEPTS_MAINTENANCE_TOOLTIP]Maintenance[/TIP] on [icon:SPECIALIST] [TIP:LOC_PEDIA_CONCEPTS_SPECIALIST_TOOLTIP]Specialists[/TIP] adjacent to Mountains. +1 [icon:YIELD_HAPPINESS] [TIP:LOC_PEDIA_CONCEPTS_MAINTENANCE_TOOLTIP]Maintenance[/TIP] on [icon:SPECIALIST] [TIP:LOC_PEDIA_CONCEPTS_SPECIALIST_TOOLTIP]Specialists[/TIP] not adjacent to Mountains.', '|TERRAIN_MOUNTAIN|', 2, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_PACHACUTI__B03', 'LEADER_PACHACUTI', 'TRAIT_LEADER_PACHACUTI_ABILITY', 'bullet', 3, 1, NULL, '[icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Cities[/TIP] gain a bonus to [icon:YIELD_PRODUCTION] Production equal to 10% of that City’s [icon:YIELD_FOOD] Food.', NULL, 3, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_Patchouli__AGENDA', 'LEADER_Patchouli', 'TRAIT_LEADER_PATCHOULI_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 0, 1, 'MAO-Leader-Patchouli', NULL),
  ('LEADER_Patchouli__B01', 'LEADER_Patchouli', 'TRAIT_LEADER_PATCHOULI_ABILITY', 'bullet', 1, 1, NULL, '[B]Seven Elements Archive:[/B] When constructing [icon:BUILDING_LIBRARY]Libraries and the [icon:WONDER]Great Library wonder, gain [icon:YIELD_PRODUCTION][B]+60% Production[/B]. When constructing other [icon:YIELD_SCIENCE]science buildings, gain [icon:YIELD_PRODUCTION][B]+30% Production[/B].', NULL, 3, '|WONDER_GREAT_LIBRARY|BUILDING_LIBRARY|', 1, 1, 1, 1, 'MAO-Leader-Patchouli', NULL),
  ('LEADER_Patchouli__B02', 'LEADER_Patchouli', 'TRAIT_LEADER_PATCHOULI_ABILITY', 'bullet', 2, 1, NULL, '[B]Power of Knowledge:[/B] All buildings with [icon:GREATWORK]Great Work slots gain [B]+1[/B] [icon:GREATWORK]Great Work slot. For each [icon:GREATWORK]Great Work you own, all cities gain [B]+4/8/16[/B][icon:YIELD_SCIENCE]Science, [B]+2/4/8[/B][icon:YIELD_HAPPINESS]Happiness (scales with Age).', NULL, 4, NULL, 1, 1, 1, 1, 'MAO-Leader-Patchouli', NULL),
  ('LEADER_Patchouli__B03', 'LEADER_Patchouli', 'TRAIT_LEADER_PATCHOULI_ABILITY', 'bullet', 3, 1, NULL, '[B]Endless Pursuit of Knowledge:[/B] Researching [icon:RADIAL_TECH]Future Tech grants [B]+30% efficiency[/B].[/LIST]', NULL, 1, NULL, 1, 1, 1, 1, 'MAO-Leader-Patchouli', NULL),
  ('LEADER_QINSHIHUANG__AGENDA', 'LEADER_QINSHIHUANG', 'TRAIT_LEADER_QINSHIHUANG_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 0, 1, 'MAO-Leader-QINSHIHUANG', NULL);
INSERT OR IGNORE INTO LShufMapping (PieceId, LeaderType, AbilityTrait, Kind, BulletIndex, BulletCount, BulletList, BulletText, BiasTags, Value, SpecificTo, Movable, Reviewed, Guess, IsModded, ModId, Note) VALUES
  ('LEADER_QINSHIHUANG__B01', 'LEADER_QINSHIHUANG', 'TRAIT_LEADER_QINSHIHUANG_ABILITY', 'bullet', 1, 1, NULL, '[B]First Emperor:[/B] [icon:MOD_SETTLEMENT_LIMIT] Settlement Cap [B]+3[/B]. Start with [icon:TRADITION] Tradition slot [B]+1[/B].', NULL, 4, NULL, 1, 1, 1, 1, 'MAO-Leader-QINSHIHUANG', NULL),
  ('LEADER_QINSHIHUANG__B02', 'LEADER_QINSHIHUANG', 'TRAIT_LEADER_QINSHIHUANG_ABILITY', 'bullet', 2, 1, NULL, '[B]Commandery System:[/B] Each Tradition grants all Settlements [icon:YIELD_FOOD] [B]+2[/B] [icon:YIELD_GOLD] [B]+2[/B]. [B]Non-capital[/B] Settlements [icon:YIELD_HAPPINESS] [B]-5[/B], but [icon:YIELD_PRODUCTION] [icon:YIELD_FOOD] [B]+10%[/B].', NULL, 4, NULL, 1, 1, 1, 1, 'MAO-Leader-QINSHIHUANG', 'The three penalty and bonus lines use REQUIREMENT_CITY_IS_CAPITAL (not inverted) although the text says non-capital settlements. That''s the mod''s own behavior and moves as is.'),
  ('LEADER_QINSHIHUANG__B03', 'LEADER_QINSHIHUANG', 'TRAIT_LEADER_QINSHIHUANG_ABILITY', 'bullet', 3, 1, NULL, '[B]Great Wall:[/B] Building [icon:CITY_FORTIFIED][B]Fortifications[/B] (Walls, Fortresses, etc.) and [icon:WONDER][B]Defensive Wonders[/B] [icon:YIELD_PRODUCTION] [B]+30%[/B]. When playing as [icon:CIVILIZATION_HAN][B]Han[/B] or [icon:CIVILIZATION_MING][B]Ming[/B], building [icon:IMPROVEMENT_HAN_GREAT_WALL][icon:IMPROVEMENT_MING_GREAT_WALL][B]Great Wall[/B] [icon:YIELD_PRODUCTION] [B]+30%[/B] additional.', NULL, 2, '|IMPROVEMENT_HAN_GREAT_WALL|CIVILIZATION_HAN|CIVILIZATION_MING|', 1, 1, 1, 1, 'MAO-Leader-QINSHIHUANG', NULL),
  ('LEADER_REMILIA__AGENDA', 'LEADER_REMILIA', 'TRAIT_LEADER_REMILIA_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 0, 1, 'MAO-Leader-REMILIA', NULL),
  ('LEADER_SAYYIDA_AL_HURRA__AGENDA', 'LEADER_SAYYIDA_AL_HURRA', 'TRAIT_LEADER_SAYYIDA_AL_HURRA_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, '|UNIT_CLASS_NAVAL|', 1, 1, 0, 0, NULL, NULL),
  ('LEADER_SAYYIDA_AL_HURRA__B01', 'LEADER_SAYYIDA_AL_HURRA', 'TRAIT_LEADER_SAYYIDA_AL_HURRA_ABILITY', 'bullet', 1, 1, NULL, 'Receive the strongest [B]Naval Unit [/B]every time you succeed in an [B][icon:ESPIONAGE] Espionage Action[/B], if you can place a Naval Unit.', '|COAST|', 3, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_SAYYIDA_AL_HURRA__B02', 'LEADER_SAYYIDA_AL_HURRA', 'TRAIT_LEADER_SAYYIDA_AL_HURRA_ABILITY', 'bullet', 2, 1, NULL, '[B]+2 [icon:YIELD_CULTURE] Culture[/B] and [B]+1 [icon:YIELD_DIPLOMACY] Influence[/B] per Age for every [B]Naval Unit[/B] stationed on a [icon:CITY_URBAN] [B]District [/B].', '|COAST|', 3, '|UNIT_CLASS_NAVAL|', 1, 1, 1, 0, NULL, NULL),
  ('LEADER_SAYYIDA_AL_HURRA__B03', 'LEADER_SAYYIDA_AL_HURRA', 'TRAIT_LEADER_SAYYIDA_AL_HURRA_ABILITY', 'bullet', 3, 1, NULL, 'No [B][icon:YIELD_DIPLOMACY] Influence[/B] penalty for your [B][icon:ESPIONAGE] Espionage[/B] being revealed.', NULL, 1, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_SAYYIDA_AL_HURRA__B04', 'LEADER_SAYYIDA_AL_HURRA', 'TRAIT_LEADER_SAYYIDA_AL_HURRA_ABILITY', 'bullet', 4, 1, NULL, 'Opponents cannot use [B]Counter Spy[/B] against you.[/LIST]', NULL, 2, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_Shelly__AGENDA', 'LEADER_Shelly', 'TRAIT_LEADER_Shelly_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 0, 1, 'MAO-Leader-MahoShojoWitchTrial', NULL),
  ('LEADER_Shelly__B01', 'LEADER_Shelly', 'TRAIT_LEADER_Shelly_ABILITY', 'bullet', 1, 1, NULL, '[B]Crusher[/B]: [B]Melee units[/B] ignore the [icon:DAMAGED][B]wounded penalty[/B]. [B]+5[/B] [icon:NAR_REW_COMBAT][B]Combat Strength[/B] against [icon:CITY_URBAN][B]Districts[/B], ignore Zone of Control, and take [B]110%[/B] damage. [icon:UNIT_SCOUT][B]Recon units[/B] can ignore borders and enter foreign territory.[/LI][N][BLIST]', NULL, 3, '|UNIT_CLASS_MELEE|UNIT_CLASS_RECON|', 1, 1, 1, 1, 'MAO-Leader-MahoShojoWitchTrial', NULL),
  ('LEADER_Shelly__B02', 'LEADER_Shelly', 'TRAIT_LEADER_Shelly_ABILITY', 'bullet', 2, 1, NULL, '[B]Bumbling Detective[/B]: [icon:ESPIONAGE][B]Espionage Actions[/B] take [B]+50%[/B] time to complete. On a successful [icon:ESPIONAGE][B]Espionage Action[/B], gain [B]+50/100/200[/B] [icon:YIELD_DIPLOMACY][B]Influence[/B].[/LI]', NULL, 2, NULL, 1, 1, 1, 1, 'MAO-Leader-MahoShojoWitchTrial', NULL),
  ('LEADER_TECUMSEH__AGENDA', 'LEADER_TECUMSEH', 'TRAIT_LEADER_TECUMSEH_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 1, 0, NULL, 'Includes agenda modifiers beyond DIPLOMACY_AGENDA_TIMED_UPDATE; check they belong with the personality.'),
  ('LEADER_TECUMSEH__B01', 'LEADER_TECUMSEH', 'TRAIT_LEADER_TECUMSEH_ABILITY', 'bullet', 1, 1, NULL, '[B]+1 [icon:YIELD_FOOD] Food[/B] per [TIP:LOC_PEDIA_CONCEPTS_AGE_TOOLTIP]Age[/TIP] in [B][icon:YIELD_TOWNS] [TIP:LOC_PEDIA_CONCEPTS_TOWN_TOOLTIP]Towns[/TIP][/B] and [B]+1 [icon:YIELD_PRODUCTION] Production[/B] per Age in [B][icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Cities[/TIP][/B] for every [B][icon:CITYSTATE] [TIP:LOC_PEDIA_CONCEPTS_CITY_STATE_TOOLTIP]City-State[/TIP][/B] you are [B][TIP:LOC_PEDIA_CONCEPTS_SUZERAIN_TOOLTIP]Suzerain[/TIP][/B] of.', NULL, 3, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_TECUMSEH__B02', 'LEADER_TECUMSEH', 'TRAIT_LEADER_TECUMSEH_ABILITY', 'bullet', 2, 1, NULL, '[B]+1 [icon:NAR_REW_COMBAT] Combat Strength[/B] for all [B][TIP:LOC_PEDIA_CONCEPTS_INFANTRY_UNITS_TOOLTIP]Infantry[/TIP][/B] and [B][TIP:LOC_PEDIA_CONCEPTS_RANGED_UNITS_TOOLTIP]Ranged units[/TIP][/B] for every [B][icon:CITYSTATE] [TIP:LOC_PEDIA_CONCEPTS_CITY_STATE_TOOLTIP]City-State[/TIP][/B] you are [B][TIP:LOC_PEDIA_CONCEPTS_SUZERAIN_TOOLTIP]Suzerain[/TIP][/B] of.', NULL, 2, '|UNIT_CLASS_INFANTRY|UNIT_CLASS_RANGED|', 1, 1, 1, 0, NULL, NULL),
  ('LEADER_TECUMSEH__B03', 'LEADER_TECUMSEH', 'TRAIT_LEADER_TECUMSEH_ABILITY', 'bullet', 3, 1, NULL, '[B]+2 [icon:MILITARY_VP] [TIP:LOC_PEDIA_CONCEPTS_DOMINION_TOOLTIP]Dominion[/TIP][/B] for every [B][icon:CITYSTATE] [TIP:LOC_PEDIA_CONCEPTS_CITY_STATE_TOOLTIP]City-State[/TIP][/B] you are [B][TIP:LOC_PEDIA_CONCEPTS_SUZERAIN_TOOLTIP]Suzerain[/TIP][/B] of.', NULL, 2, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_TECUMSEH__B04', 'LEADER_TECUMSEH', 'TRAIT_LEADER_TECUMSEH_ABILITY', 'bullet', 4, 1, NULL, 'All [B][icon:INDEPENDENT_POWER] [TIP:LOC_PEDIA_CONCEPTS_INDEPENDENT_POWER_TOOLTIP]Independent Powers[/TIP][/B] start [B][icon:PLAYER_RELATIONSHIP_FRIENDLY] Friendly[/B] with you.', NULL, 3, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_TOYOTOMI_HIDEYOSHI__AGENDA', 'LEADER_TOYOTOMI_HIDEYOSHI', 'TRAIT_LEADER_TOYOTOMI_HIDEYOSHI_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 0, 0, NULL, NULL),
  ('LEADER_TOYOTOMI_HIDEYOSHI__B01', 'LEADER_TOYOTOMI_HIDEYOSHI', 'TRAIT_LEADER_TOYOTOMI_HIDEYOSHI_ABILITY', 'bullet', 1, 1, NULL, '[TIP:LOC_PEDIA_CONCEPTS_LAND_UNITS_TOOLTIP]Land Units[/TIP] deal [b][icon:DAMAGED] Double Damage[/b] attacking opposing Units but all of your Units take [b][icon:DAMAGED] Double Damage[/b] when defending.', NULL, 3, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_TOYOTOMI_HIDEYOSHI__B02', 'LEADER_TOYOTOMI_HIDEYOSHI', 'TRAIT_LEADER_TOYOTOMI_HIDEYOSHI_ABILITY', 'bullet', 2, 1, NULL, 'Your Units [b][icon:Action_Heal] Heal[/b] an additional 5 HP, this is doubled if on a [b][icon:YIELD_CULTURE] Culture [/b][TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Building[/TIP] or [B][icon:WONDER] Wonder[/B].', NULL, 2, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_TOYOTOMI_HIDEYOSHI__B03', 'LEADER_TOYOTOMI_HIDEYOSHI', 'TRAIT_LEADER_TOYOTOMI_HIDEYOSHI_ABILITY', 'bullet', 3, 1, NULL, '[b]+25% [icon:YIELD_PRODUCTION] Production[/b] towards [b][icon:YIELD_CULTURE] Culture Buildings[/b]. This is [b]doubled[/b] in [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Captured Cities[/TIP] from any Age.[/LIST]', NULL, 2, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_TRUNG_TRAC__AGENDA', 'LEADER_TRUNG_TRAC', 'TRAIT_LEADER_TRUNG_TRAC_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 0, 0, NULL, NULL),
  ('LEADER_TRUNG_TRAC__B01', 'LEADER_TRUNG_TRAC', 'TRAIT_LEADER_TRUNG_TRAC_ABILITY', 'bullet', 1, 1, NULL, 'Gain the Unique [icon:UNIT_ARMY_COMMANDER] [TIP:LOC_PEDIA_CONCEPTS_COMMANDER_TOOLTIP]Army Commander[/TIP] Trung Nhi after obtaining your first Land [TIP:LOC_PEDIA_CONCEPTS_MILITARY_UNIT_TOOLTIP]Military Unit[/TIP] of the [TIP:LOC_PEDIA_CONCEPTS_AGE_TOOLTIP]Age[/TIP]. [icon:UNIT_ARMY_COMMANDER] Trung Nhi persists across [TIP:LOC_PEDIA_CONCEPTS_AGE_TOOLTIP]Age[/TIP] Transitions, and begins with 2 [icon:NAR_REW_PROMOTION] Promotions in Exploration Advanced Starts or 3 [icon:NAR_REW_PROMOTION] Promotions in Modern Advanced Starts, and has a unique  [TIP:LOC_PEDIA_CONCEPTS_PROMOTION_TOOLTIP]Promotion[/TIP] Tree.', NULL, 4, '|UNIT_TRUNG_NHI|UNIT_CLASS_TRUNG_NHI|', 1, 1, 1, 0, NULL, 'UNIT_TRUNG_NHI has no TraitType, so another leader can be given the unit. Her unique promotion tree and age-transition persistence are on the unit, not this trait; a lab check should confirm they come along.'),
  ('LEADER_TRUNG_TRAC__B02', 'LEADER_TRUNG_TRAC', 'TRAIT_LEADER_TRUNG_TRAC_ABILITY', 'bullet', 2, 1, NULL, '+20% [icon:UNIT_ARMY_COMMANDER] [TIP:LOC_PEDIA_CONCEPTS_COMMANDER_EXPERIENCE_TOOLTIP]Commander Experience[/TIP].', NULL, 2, '|UNIT_CLASS_COMMAND|', 1, 1, 1, 0, NULL, NULL),
  ('LEADER_TRUNG_TRAC__B03', 'LEADER_TRUNG_TRAC', 'TRAIT_LEADER_TRUNG_TRAC_ABILITY', 'bullet', 3, 1, NULL, '+10% [icon:YIELD_SCIENCE] Science in [icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Cities[/TIP] in Tropical. This is doubled while in a [icon:WAR] Formal War you declare.', '|BIOME_TROPICAL|', 2, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_WASHINGTON__AGENDA', 'LEADER_WASHINGTON', 'TRAIT_LEADER_WASHINGTON_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 0, 0, NULL, NULL),
  ('LEADER_WASHINGTON__B01', 'LEADER_WASHINGTON', 'TRAIT_LEADER_WASHINGTON_ABILITY', 'bullet', 1, 1, NULL, 'Gain a [B][icon:UNIT_MIGRANT] Migrant[/B] in your [B][icon:NOTIFICATION_SELECT_CAPITAL] Capital[/B] when entering a [B][icon:CELEBRATION] [TIP:LOC_PEDIA_CONCEPTS_CELEBRATIONS_TOOLTIP]Celebration[/TIP][/B].', NULL, 2, '|UNIT_MIGRANT|', 1, 1, 1, 0, NULL, NULL),
  ('LEADER_WASHINGTON__B02', 'LEADER_WASHINGTON', 'TRAIT_LEADER_WASHINGTON_ABILITY', 'bullet', 2, 1, NULL, 'Start with two additional [B][icon:SOCIAL_POLICY] [TIP:LOC_PEDIA_CONCEPTS_SOCIAL_POLICY_TOOLTIP]Policies[/TIP][/B] and an additional [icon:SOCIAL_POLICY] Social Policy slot.', NULL, 4, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_WASHINGTON__B03', 'LEADER_WASHINGTON', 'TRAIT_LEADER_WASHINGTON_ABILITY', 'bullet', 3, 1, NULL, 'For each [icon:SOCIAL_POLICY] Policy, but not [icon:TRADITION] [TIP:LOC_PEDIA_CONCEPTS_TRADITION_TOOLTIP]Tradition[/TIP], slotted into your [icon:GOVERNMENT] [TIP:LOC_PEDIA_CONCEPTS_GOVERNMENT_TOOLTIP]Government[/TIP], get +1 [icon:YIELD_FOOD] Food per [TIP:LOC_PEDIA_CONCEPTS_AGE_TOOLTIP]Age[/TIP] in [icon:YIELD_TOWNS] [TIP:LOC_PEDIA_CONCEPTS_TOWN_TOOLTIP]Towns[/TIP] and +2 [icon:YIELD_HAPPINESS] Happiness per Age in [icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Cities[/TIP].', NULL, 3, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_WUZETIAN__AGENDA', 'LEADER_WUZETIAN', 'TRAIT_LEADER_WUZETIAN_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 0, 1, 'MAO-Leader-WUZETIAN', NULL),
  ('LEADER_WUZETIAN__B01', 'LEADER_WUZETIAN', 'TRAIT_LEADER_WUZETIAN_ABILITY', 'bullet', 1, 1, NULL, '[B]Imperial Privilege:[/B] [B]+30%[/B] [icon:UNIT_ARMY_COMMANDER] Commander Experience. Upon first [icon:WAR] War declaration, receive [B]3[/B] land [icon:RANGED] units in your Capital (Archer / Crossbowman / Field Cannon; swaps to unique replacements).', NULL, 3, '|UNIT_ARCHER|', 1, 1, 1, 1, 'MAO-Leader-WUZETIAN', NULL),
  ('LEADER_WUZETIAN__B02', 'LEADER_WUZETIAN', 'TRAIT_LEADER_WUZETIAN_ABILITY', 'bullet', 2, 1, NULL, '[B]Book of Denunciations:[/B] [B]+50%[/B] [icon:ESPIONAGE] Espionage efficiency. No [icon:YIELD_DIPLOMACY] Influence penalty when your [icon:ESPIONAGE] Espionage is revealed.', NULL, 2, NULL, 1, 1, 1, 1, 'MAO-Leader-WUZETIAN', NULL),
  ('LEADER_WUZETIAN__B03', 'LEADER_WUZETIAN', 'TRAIT_LEADER_WUZETIAN_ABILITY', 'bullet', 3, 1, NULL, '[B]Imperial Examination:[/B] Wu Zetian championed the examination system and employed capable ministers. [B]+25%[/B] [icon:YIELD_POPULATION] Population Growth in all Cities. [B]+1 [icon:YIELD_SCIENCE] Science[/B] and [B]+1 [icon:YIELD_CULTURE] Culture[/B] per [icon:SPECIALIST] Specialist.[/LIST]', NULL, 4, NULL, 1, 1, 1, 1, 'MAO-Leader-WUZETIAN', NULL),
  ('LEADER_XERXES_ALT__AGENDA', 'LEADER_XERXES_ALT', 'TRAIT_LEADER_XERXES_ALT_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 0, 0, NULL, NULL),
  ('LEADER_XERXES_ALT__B01', 'LEADER_XERXES_ALT', 'TRAIT_LEADER_XERXES_ALT_ABILITY', 'bullet', 1, 1, NULL, '+1 [icon:TRADE_ROUTE] [TIP:LOC_PEDIA_CONCEPTS_TRADE_ROUTE_TOOLTIP]Trade Route[/TIP] Limit with all other Leaders.', NULL, 3, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_XERXES_ALT__B02', 'LEADER_XERXES_ALT', 'TRAIT_LEADER_XERXES_ALT_ABILITY', 'bullet', 2, 1, NULL, '+10 [icon:TRADE_ROUTE] [TIP:LOC_PEDIA_CONCEPTS_TRADE_RANGE_TOOLTIP]Trade Range[/TIP].', NULL, 1, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_XERXES_ALT__B03', 'LEADER_XERXES_ALT', 'TRAIT_LEADER_XERXES_ALT_ABILITY', 'bullet', 3, 1, NULL, 'Gain [B]50 [icon:YIELD_CULTURE] Culture[/B] and [B]100 [icon:YIELD_GOLD] Gold[/B] per [TIP:LOC_PEDIA_CONCEPTS_AGE_TOOLTIP]Age[/TIP] when you create a [icon:TRADE_ROUTE] Trade Route or Road.', NULL, 3, '|UNIT_CLASS_MAKE_TRADE_ROUTE|', 1, 1, 1, 0, NULL, NULL),
  ('LEADER_XERXES_ALT__B04', 'LEADER_XERXES_ALT', 'TRAIT_LEADER_XERXES_ALT_ABILITY', 'bullet', 4, 1, NULL, '+1 [icon:YIELD_CULTURE] Culture and [icon:YIELD_GOLD] Gold per Age on [icon:CITY_BUILDING_LIST] [TIP:LOC_PEDIA_CONCEPTS_UNIQUE_BUILDING_TOOLTIP]Unique Buildings[/TIP] and [icon:CITY_RURAL] [TIP:LOC_PEDIA_CONCEPTS_IMPROVEMENT_TOOLTIP]Improvements[/TIP].[/LIST]', NULL, 2, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_XERXES__AGENDA', 'LEADER_XERXES', 'TRAIT_LEADER_XERXES_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 0, 0, NULL, NULL),
  ('LEADER_XERXES__B01', 'LEADER_XERXES', 'TRAIT_LEADER_XERXES_ABILITY', 'bullet', 1, 1, NULL, '+3 [icon:NAR_REW_COMBAT] [TIP:LOC_PEDIA_CONCEPTS_COMBAT_STRENGTH_TOOLTIP]Combat Strength[/TIP] for Units that are attacking in neutral or enemy territory.', NULL, 3, NULL, 1, 1, 1, 0, NULL, NULL);
INSERT OR IGNORE INTO LShufMapping (PieceId, LeaderType, AbilityTrait, Kind, BulletIndex, BulletCount, BulletList, BulletText, BiasTags, Value, SpecificTo, Movable, Reviewed, Guess, IsModded, ModId, Note) VALUES
  ('LEADER_XERXES__B02', 'LEADER_XERXES', 'TRAIT_LEADER_XERXES_ABILITY', 'bullet', 2, 1, NULL, 'Gain 100 [icon:YIELD_CULTURE] Culture and [icon:YIELD_GOLD] Gold per [TIP:LOC_PEDIA_CONCEPTS_AGE_TOOLTIP]Age[/TIP] when you capture a [TIP:LOC_PEDIA_CONCEPTS_SETTLEMENT_TOOLTIP]Settlement[/TIP] for the first time.', NULL, 2, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_XERXES__B03', 'LEADER_XERXES', 'TRAIT_LEADER_XERXES_ABILITY', 'bullet', 3, 1, NULL, '+10% [icon:YIELD_GOLD] Gold in all [TIP:LOC_PEDIA_CONCEPTS_SETTLEMENT_TOOLTIP]Settlements[/TIP], doubled in [TIP:LOC_PEDIA_CONCEPTS_SETTLEMENT_TOOLTIP]Captured Settlements[/TIP] from any Age.', NULL, 3, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_XERXES__B04', 'LEADER_XERXES', 'TRAIT_LEADER_XERXES_ABILITY', 'bullet', 4, 1, NULL, '+1 [icon:SETTLEMENT_LIMIT] [TIP:LOC_PEDIA_CONCEPTS_SETTLEMENT_LIMIT_TOOLTIP]Settlement Limit[/TIP] each [TIP:LOC_PEDIA_CONCEPTS_AGE_TOOLTIP]Age[/TIP].', NULL, 4, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_YI_SUN_SIN__AGENDA', 'LEADER_YI_SUN_SIN', 'TRAIT_LEADER_YI_SUN_SIN_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, '|UNIT_CLASS_NAVAL|', 1, 1, 0, 0, NULL, NULL),
  ('LEADER_YI_SUN_SIN__B01', 'LEADER_YI_SUN_SIN', 'TRAIT_LEADER_YI_SUN_SIN_ABILITY', 'bullet', 1, 3, '1|3|4', 'Can construct [b] [icon:UNIT_FLEET_COMMANDER] Fleet [TIP:LOC_PEDIA_CONCEPTS_COMMANDER_TOOLTIP]Commanders[/TIP][/b] after studying [icon:RADIAL_CIVICS] [b] Discipline[/b] in Antiquity. Receive a [icon:UNIT_FLEET_COMMANDER] [b]Fleet Commander[/b] once you have discovered [icon:RADIAL_CIVICS] [b]Discipline[/b] and have a Harbor [TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Building[/TIP] with access to the Ocean.[N]On construction of [b]Science Buildings[/b] receive 10 XP to all [icon:UNIT_FLEET_COMMANDER] [b]Fleet Commanders[/b].[N]+3 [icon:YIELD_GOLD] [b]Gold[/b] per [TIP:LOC_PEDIA_CONCEPTS_AGE_TOOLTIP]Age[/TIP] for every [icon:UNIT_FLEET_COMMANDER] [b]Fleet Commander[/b] XP earned in Combat.[/LIST]', '|COAST|', 4, '|UNIT_CLASS_FLEET_COMMANDER|BUILDING_HARBOR|', 1, 1, 1, 0, NULL, 'Building fleet commanders in Antiquity comes from TRAIT_UNLOCK_FLEET_COMMANDER (UNIT_FLEET_COMMANDER''s TraitType) and the Discipline civic unlock, which both stay with Yi Sun-sin (CONTRACTS 12.4). Another leader holding this piece may get the free commander without being able to build more; whether the grant works without the trait is a lab check. Bullet 3 merged in: its Fleet Commanders come from bullet 1 in Antiquity. Bullet 4 merged in: its Fleet Commanders come from bullet 1 in Antiquity.'),
  ('LEADER_YI_SUN_SIN__B02', 'LEADER_YI_SUN_SIN', 'TRAIT_LEADER_YI_SUN_SIN_ABILITY', 'bullet', 2, 1, NULL, 'Defeating an enemy with a Naval Unit provides [icon:YIELD_SCIENCE] [b]Science [/b]equal to [b]100% [/b]of the defeated unit''s [icon:NAR_REW_COMBAT] [TIP:LOC_PEDIA_CONCEPTS_COMBAT_STRENGTH_TOOLTIP]Combat Strength[/TIP].', '|COAST|', 2, NULL, 1, 1, 1, 0, NULL, NULL),
  ('LEADER_Yamada__AGENDA', 'LEADER_Yamada', 'TRAIT_LEADER_Yamada_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 0, 1, 'MAO-Leader-Yamada', NULL),
  ('LEADER_Yamada__B01', 'LEADER_Yamada', 'TRAIT_LEADER_Yamada_ABILITY', 'bullet', 1, 1, NULL, '[B]Bass Solo:[/B] [B]All[/B] [icon:YIELD_CULTURE]Culture buildings gain [icon:YIELD_SCIENCE]Science adjacency; each [icon:YIELD_CULTURE]Culture building built grants [B]+100[/B][icon:YIELD_GOLD] Gold (scales with Age).[/LI][N][BLIST]', NULL, 3, NULL, 1, 1, 1, 1, 'MAO-Leader-Yamada', NULL),
  ('LEADER_Yamada__B02', 'LEADER_Yamada', 'TRAIT_LEADER_Yamada_ABILITY', 'bullet', 2, 1, NULL, '[B]Cool Weirdo:[/B] Each [icon:PLAYER_RELATIONSHIP_NEUTRAL][B]Neutral[/B] relationship grants [B]+3[/B][icon:YIELD_CULTURE] Culture (scales with Age).[/LI][N][BLIST]', NULL, 2, NULL, 1, 1, 1, 1, 'MAO-Leader-Yamada', NULL),
  ('LEADER_Yamada__B03', 'LEADER_Yamada', 'TRAIT_LEADER_Yamada_ABILITY', 'bullet', 3, 1, NULL, '[B]Living on Weeds:[/B] When [icon:YIELD_GOLD]Gold per turn is negative, [icon:YIELD_CULTURE][B]+30%[/B] Culture and [icon:YIELD_SCIENCE][B]+30%[/B] Science; when positive, [icon:YIELD_CULTURE][B]+15%[/B] Culture only.[/LI]', NULL, 3, NULL, 1, 1, 1, 1, 'MAO-Leader-Yamada', NULL),
  ('LEADER_Youmu__AGENDA', 'LEADER_Youmu', 'TRAIT_LEADER_YOUMU_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 0, 1, 'MAO-Leader-Youmu', NULL),
  ('LEADER_Youmu__B01', 'LEADER_Youmu', 'TRAIT_LEADER_YOUMU_ABILITY', 'bullet', 1, 1, NULL, '[B]Half-Phantom Gardener:[/B] [icon:YIELD_WAREHOUSE] [B]Warehouse Buildings[/B] gain [B]+1[/B][icon:YIELD_PRODUCTION] [B]Production[/B] from [B]adjacent[/B] [icon:RES_ANY] resources ([icon:AGE_EXPLORATION] [B]Exploration[/B] adds [B]+1[/B][icon:YIELD_CULTURE] [B]Culture[/B], [icon:AGE_MODERN] [B]Modern[/B] adds [B]+1[/B][icon:YIELD_SCIENCE] [B]Science[/B]). [icon:BUILDING_GARDEN] [B]Gardens[/B] gain [B]+6[/B][icon:YIELD_FOOD] [B]Food[/B] [B]+6[/B][icon:YIELD_HAPPINESS] [B]Happiness[/B], [icon:BUILDING_PAVILION] [B]Pavilions[/B] gain [B]+8[/B][icon:YIELD_FOOD] [B]Food[/B] [B]+8[/B][icon:YIELD_HAPPINESS] [B]Happiness[/B], [icon:BUILDING_CITY_PARK] [B]City Parks[/B] gain [B]+12[/B][icon:YIELD_FOOD] [B]Food[/B] [B]+12[/B][icon:YIELD_HAPPINESS] [B]Happiness[/B].', NULL, 4, '|BUILDING_GARDEN|', 1, 1, 1, 1, 'MAO-Leader-Youmu', NULL),
  ('LEADER_Youmu__B02', 'LEADER_Youmu', 'TRAIT_LEADER_YOUMU_ABILITY', 'bullet', 2, 1, NULL, '[B]Nitoryu:[/B] [icon:UNIT_CLASS_INFANTRY] [B]Infantry[/B] gains [B]+3[/B][icon:STAT_COMBAT] [B]Combat Strength[/B] when [B]attacking[/B] [icon:DISTRICT] [B]district defenses[/B] ([B]+5[/B] during [icon:CELEBRATION] [B]celebrations[/B], also applies to [B]enemy units[/B]). [B]All units[/B] [B]ignore[/B] enemy [B]rough terrain[/B] [B]defense bonuses[/B].[/LIST][NEWLINE][I]"I sever all illusions—my blade leaves no shadow." —Youmu Konpaku[/I]', NULL, 3, '|UNIT_CLASS_MELEE|UNIT_CLASS_INFANTRY|', 1, 1, 1, 1, 'MAO-Leader-Youmu', NULL),
  ('LEADER_Yuyuko__AGENDA', 'LEADER_Yuyuko', 'TRAIT_LEADER_Yuyuko_ABILITY', 'agenda', NULL, 1, NULL, NULL, NULL, 1, NULL, 1, 1, 0, 1, 'MAO-Leader-Yuyuko', NULL);

